/**
 * Breakdown content — what a "+N" chip or a total opens.
 *
 * The anatomy is the DS's own, copied from `InvoiceCard` (Figma "Invoice"
 * 27599:62303) — the only hover-card content pattern in the DS, and the one the
 * DS DataTable puts in its Amount column:
 *
 *   flex w-full flex-col gap-4
 *     h4  text-base font-semibold          ← title, foreground (not a muted label)
 *     border-t border-dashed border-border  ← rule under the title
 *     flex flex-col gap-1                   ← detail rows
 *       flex items-center justify-between text-sm text-muted-foreground
 *       …value spans carry tabular-nums
 *     border-t border-dashed border-border  ← rule before the total
 *     flex items-center justify-between text-base font-semibold  ← total
 *
 * The container keeps `HoverCardContent`'s default `p-4`; width is the only
 * override, which is the one the DS itself makes (`w-[380px]` for the Invoice
 * card). Rows with no `value` render as a plain list (the products case).
 */
export interface BreakdownRow {
  label: string;
  /** Omit for a label-only list. */
  value?: string;
  /**
   * A second line under the label — what the row carries (Pavan, 2026-10-14:
   * an asset's products under its name, its capacity as the value).
   */
  sub?: string;
}

/**
 * A GROUPED TABLE instead of rows (Pavan, 2026-10-14 — a ship-to's products,
 * each with its assets, their type and capacity). Same card: title, dashed
 * rule, the card's own type sizes; a header row, then a band per group.
 */
export interface BreakdownTable {
  columns: { label: string; align?: "left" | "right" }[];
  groups: { label: string; rows: string[][] }[];
}

export interface BreakdownCardProps {
  title: string;
  rows: BreakdownRow[];
  table?: BreakdownTable;
  /** Renders the dashed rule + bold total row. Omit to end after the rows. */
  total?: { label: string; value: string };
  /** WARNINGS, after the total (Pavan, 2026-10-20) — red, an alert mark each:
      what the figure means will go wrong. */
  warnings?: string[];
}

export function BreakdownCard({ title, rows, table, total, warnings }: BreakdownCardProps) {
  return (
    <div className="flex w-full flex-col gap-4">
      <h4 className="text-base font-semibold">{title}</h4>
      <div className="border-t border-dashed border-border" />

      {table && (
        <table className="w-full table-fixed text-sm">
          <thead>
            <tr className="text-xs text-muted-foreground">
              {table.columns.map((c) => (
                <th key={c.label} className={cn("pb-1.5 font-medium", c.align === "right" ? "" : "text-left")}>
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          {table.groups.map((g) => (
            <tbody key={g.label}>
              {/* THE GROUP — its name on a quiet band across the table; an
                  unnamed group (a plain table) has no band. */}
              {g.label && <tr>
                <td colSpan={table.columns.length} className="pt-2">
                  <span className="block rounded-sm bg-fp-table-header px-2 py-1 text-xs font-semibold text-foreground">
                    {g.label}
                  </span>
                </td>
              </tr>}
              {g.rows.map((r, i) => (
                <tr key={i} className="text-muted-foreground">
                  {r.map((cell, j) => (
                    <td
                      key={j}
                      /* THE NAME TRUNCATES; the rest wrap, so a list of
                         products is read whole. */
                      className={cn(
                        "py-1 pr-2 align-top",
                        j === 0 ? "truncate pl-2 text-foreground" : "break-words",
                        table.columns[j]?.align === "right" && "text-right tabular-nums"
                      )}
                      title={cell}
                    >
                      {cell}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          ))}
        </table>
      )}

      <div className="flex flex-col gap-1">
        {rows.map((row, i) => (
          <div
            key={`${row.label}-${i}`}
            className={cn(
              "flex justify-between gap-6 text-sm text-muted-foreground",
              row.sub ? "items-baseline py-0.5" : "items-center"
            )}
          >
            {row.sub ? (
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-foreground">{row.label}</span>
                <span className="text-xs">{row.sub}</span>
              </span>
            ) : (
              <span className="min-w-0 truncate">{row.label}</span>
            )}
            {row.value && (
              <span className="shrink-0 tabular-nums">{row.value}</span>
            )}
          </div>
        ))}
      </div>

      {total && (
        <>
          <div className="border-t border-dashed border-border" />
          <div className="flex items-center justify-between gap-6 text-base font-semibold">
            <span>{total.label}</span>
            <span className="tabular-nums">{total.value}</span>
          </div>
        </>
      )}

      {warnings && warnings.length > 0 && (
        <ul className="flex flex-col gap-1.5">
          {warnings.map((w) => (
            <li key={w} className="flex items-start gap-2 text-sm text-status-failed">
              <TriangleAlert aria-hidden className="mt-0.5 size-4 shrink-0" />
              <span>{w}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/*
  ONE WAY TO OPEN A BREAKDOWN, EVERYWHERE (Pavan, 2026-10-14). A "+N" chip —
  or, where the whole cell IS the figure (a quantity), the figure — opens the
  card ON CLICK, above the cell. Not hover: touch cannot hover, and a card
  that appears under a passing pointer is one nobody asked for. The press
  stays in the cell: a row that opens its record on click must not open it
  as well.
*/
export function BreakdownPopover({
  trigger,
  label,
  card,
  width = 280,
  align = "start",
  className,
}: {
  /** The pressable face — a chip, or the figure. */
  trigger: React.ReactNode;
  /** What the press does, for a screen reader. */
  label: string;
  card: BreakdownCardProps;
  width?: number;
  align?: "start" | "end";
  className?: string;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={label}
          onClick={(e) => e.stopPropagation()}
          className={cn(
            "shrink-0 cursor-pointer rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
            className
          )}
        >
          {trigger}
        </button>
      </PopoverTrigger>
      <PopoverContent
        align={align}
        side="top"
        style={{ width }}
        className="max-h-96 overflow-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <BreakdownCard {...card} />
      </PopoverContent>
    </Popover>
  );
}

/** The "+N" chip that opens a breakdown. */
export function OverflowChip({
  count,
  label,
  card,
  width,
}: {
  count: number;
  label: string;
  card: BreakdownCardProps;
  width?: number;
}) {
  return (
    <BreakdownPopover
      label={label}
      card={card}
      width={width}
      trigger={<Pill className="cursor-pointer tabular-nums">+{count}</Pill>}
    />
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/*
  THE MODULE DASHBOARD'S PARTS (Pavan, 2026-10-05) — shared by 3PL and Sales.

  EVERYTHING ON A DASHBOARD IS A WAY INTO A LIST. A number, a bar or a row is
  pressed to open the list it counts, already narrowed to exactly those rows,
  so the dashboard never states a figure the reader cannot go and check.

  WHITE CARDS ON A GROUND (2026-10-05, after the reference dashboard): the
  dashboard sits on the inner-panel grey and every card is the content layer,
  borderless, rounded large. In dark the two swap so the cards still sit
  above their ground.

  COLOUR BY THE JOB IT DOES, from the validated `--fp-viz-*` palette:
  · a count over stages or time is ONE series — slot 1 blue, the peak lit and
    the rest a quiet tint of it, so the eye finds the busiest bar first;
  · a share of a whole is IDENTITY — one segment per part in the palette's
    fixed order, with a dot beside each name so colour is never alone;
  · a ranking is ONE series again — slot 1 blue throughout.
*/

/** The dashboard's ground — wraps the cards. */
export const DASHBOARD_GROUND = "rounded-xl bg-fp-surface-1a p-3 dark:bg-fp-surface-1b";
const CARD = "rounded-xl bg-fp-surface-1b shadow-xs dark:bg-fp-surface-1a";

const BAR = "bg-fp-viz-1";
/** Categorical slots in their fixed order. Literal so Tailwind keeps them. */
const VIZ = [
  "bg-fp-viz-1",
  "bg-fp-viz-2",
  "bg-fp-viz-3",
  "bg-fp-viz-4",
  "bg-fp-viz-5",
  "bg-fp-viz-6",
  "bg-fp-viz-7",
  "bg-fp-viz-8",
];

export function Panel({
  title,
  aside,
  className,
  children,
}: {
  title: string;
  aside?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <section className={cn("flex min-w-0 flex-col", CARD, className)}>
      <header className="flex items-baseline justify-between gap-3 px-5 pt-4">
        <h3 className="text-base font-semibold text-foreground">{title}</h3>
        {aside && <span className="text-xs text-muted-foreground">{aside}</span>}
      </header>
      <div className="min-w-0 flex-1 px-5 pt-4 pb-5">{children}</div>
    </section>
  );
}

/** A headline number. Pressing it opens the rows it counts. */
export function StatTile({
  label,
  value,
  note,
  onOpen,
}: {
  label: string;
  value: string;
  note?: string;
  onOpen?: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onOpen}
      disabled={!onOpen}
      className={cn(
        "flex min-w-0 flex-col items-start gap-2 p-5 text-left outline-none transition-shadow enabled:hover:shadow-sm focus-visible:ring-2 focus-visible:ring-ring/50",
        CARD
      )}
    >
      <span className="text-sm font-medium text-foreground">{label}</span>
      <span className="text-3xl font-semibold tabular-nums text-foreground">{value}</span>
      {note && <span className="text-xs text-muted-foreground">{note}</span>}
    </button>
  );
}

export interface BarDatum {
  key: string;
  label: string;
  value: number;
  /** What the tooltip says, e.g. "3 orders · $9,323". */
  detail?: string;
  onOpen?: () => void;
}

/**
 * VERTICAL BARS — a count per stage or per day. The value sits above each
 * bar and the label under it; hover names it in full; press opens it. Bars
 * keep a 4px rounded top on a shared baseline and a 2px gap between them.
 */
export function BarColumns({ data, height = 140 }: { data: BarDatum[]; height?: number }) {
  const max = Math.max(1, ...data.map((d) => d.value));
  /* THE PEAK IS LIT — the first bar at the maximum, when there is one. */
  const peak = data.findIndex((d) => d.value === max && d.value > 0);
  return (
    <div className="flex items-end gap-0.5" style={{ height: height + 40 }}>
      {data.map((d, i) => (
        <Tooltip key={d.key}>
          <TooltipTrigger asChild>
            <button
              type="button"
              onClick={d.onOpen}
              disabled={!d.onOpen}
              className="group flex min-w-0 flex-1 flex-col items-center gap-1.5 rounded-sm px-0.5 outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <span
                className={cn(
                  "text-xs tabular-nums",
                  i === peak ? "font-semibold text-foreground" : "text-muted-foreground"
                )}
              >
                {d.value}
              </span>
              <span className="flex w-full items-end justify-center" style={{ height }}>
                <span
                  className={cn(
                    "w-full max-w-11 rounded-md transition-colors",
                    d.value === 0
                      ? "bg-fp-outline-1"
                      : i === peak
                        ? BAR
                        : "bg-fp-viz-1/15 group-hover:bg-fp-viz-1/40 dark:bg-fp-viz-1/25 dark:group-hover:bg-fp-viz-1/50"
                  )}
                  style={{ height: d.value > 0 ? Math.max(6, (d.value / max) * height) : 3 }}
                />
              </span>
              <span
                className={cn(
                  "w-full truncate text-center text-xs",
                  i === peak ? "font-medium text-foreground" : "text-muted-foreground"
                )}
              >
                {d.label}
              </span>
            </button>
          </TooltipTrigger>
          <TooltipContent>
            <span className="font-medium">{d.label}</span>
            {" · "}
            {d.detail ?? d.value}
          </TooltipContent>
        </Tooltip>
      ))}
    </div>
  );
}

/**
 * A RANKED LIST WITH BARS — share of a whole, or the top few of something.
 * Name on the left, the figure and its share on the right, the bar under the
 * name. Press a row to open it.
 */
export function BarList({
  data,
  format = (n) => n.toLocaleString(),
  share = false,
}: {
  data: BarDatum[];
  format?: (n: number) => string;
  /**
   * A SHARE OF A WHOLE: one segmented bar across the top, a segment per part
   * in the palette's fixed order, and a coloured dot beside each name below.
   * A ninth part and beyond fold into the last slot's neighbour — keep
   * shares to eight.
   */
  share?: boolean;
}) {
  const total = data.reduce((s, d) => s + d.value, 0) || 1;
  const max = Math.max(1, ...data.map((d) => d.value));
  if (data.length === 0)
    return <p className="py-6 text-center text-sm text-muted-foreground">Nothing in this range.</p>;
  if (share) return <ShareBar data={data} format={format} total={total} />;
  return (
    <ul className="flex flex-col gap-1">
      {data.map((d) => (
        <li key={d.key}>
          <Tooltip>
            <TooltipTrigger asChild>
              <button
                type="button"
                onClick={d.onOpen}
                disabled={!d.onOpen}
                className="flex w-full flex-col gap-1 rounded-md px-2 py-1.5 text-left outline-none transition-colors enabled:hover:bg-accent/50 focus-visible:ring-2 focus-visible:ring-ring/50"
              >
                <span className="flex items-baseline justify-between gap-3 text-sm">
                  <span className="truncate text-foreground">{d.label}</span>
                  <span className="shrink-0 tabular-nums text-foreground">
                    {format(d.value)}
                    <span className="ml-2 inline-block w-10 text-right text-xs text-muted-foreground">
                      {Math.round((d.value / total) * 100)}%
                    </span>
                  </span>
                </span>
                <span className="h-2 w-full rounded-full bg-fp-viz-1/12 dark:bg-fp-viz-1/20">
                  <span
                    className={cn("block h-full rounded-full", BAR)}
                    style={{ width: `${(d.value / max) * 100}%` }}
                  />
                </span>
              </button>
            </TooltipTrigger>
            <TooltipContent>
              <span className="font-medium">{d.label}</span>
              {" · "}
              {d.detail ?? format(d.value)}
            </TooltipContent>
          </Tooltip>
        </li>
      ))}
    </ul>
  );
}

/** The share form of `BarList` — see its `share` prop. */
function ShareBar({
  data,
  format,
  total,
}: {
  data: BarDatum[];
  format: (n: number) => string;
  total: number;
}) {
  const parts = data.slice(0, VIZ.length);
  return (
    <div className="flex flex-col gap-4">
      {/* 2px surface gaps between segments; rounded only at the two ends. */}
      <div className="flex h-3 w-full gap-0.5 overflow-hidden rounded-full">
        {parts.map((d, i) =>
          d.value > 0 ? (
            <Tooltip key={d.key}>
              <TooltipTrigger asChild>
                <button
                  type="button"
                  onClick={d.onOpen}
                  disabled={!d.onOpen}
                  aria-label={`${d.label}: ${format(d.value)}`}
                  className={cn("h-full min-w-1 outline-none transition-opacity hover:opacity-80 focus-visible:ring-2 focus-visible:ring-ring/50", VIZ[i])}
                  style={{ width: `${(d.value / total) * 100}%` }}
                />
              </TooltipTrigger>
              <TooltipContent>
                <span className="font-medium">{d.label}</span>
                {" · "}
                {d.detail ?? format(d.value)}
              </TooltipContent>
            </Tooltip>
          ) : null
        )}
      </div>
      <ul className="flex flex-col gap-0.5">
        {parts.map((d, i) => (
          <li key={d.key}>
            <button
              type="button"
              onClick={d.onOpen}
              disabled={!d.onOpen}
              className="flex w-full items-center justify-between gap-3 rounded-md px-2 py-1.5 text-left text-sm outline-none transition-colors enabled:hover:bg-accent/50 focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <span className="flex min-w-0 items-center gap-2">
                <span aria-hidden className={cn("size-2.5 shrink-0 rounded-full", VIZ[i])} />
                <span className="truncate text-foreground">{d.label}</span>
              </span>
              <span className="shrink-0 tabular-nums text-foreground">
                {format(d.value)}
                <span className="ml-2 inline-block w-10 text-right text-xs text-muted-foreground">
                  {Math.round((d.value / total) * 100)}%
                </span>
              </span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import * as React from "react";
import { TriangleAlert, X } from "lucide-react";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { SheetField } from "@/components/side-sheet/parts";
import { HangingAdd } from "./HangingAdd";
import { Slider } from "@/components/ui/slider";
import {
  formatSpan,
  formatWindow,
} from "@/components/form-layout/TimeWindowSlider";
import { cn } from "@/lib/utils";
/** A stretch of the day, minutes from midnight. */
export interface TimeSpan {
  start: number;
  end: number;
}

/*
  DELIVERY WINDOW & PREFERRED TIME (Pavan, 2026-10-20, after his reference;
  shared by every module's order sheet) —
  ONE day, drawn once, full width. The delivery window is the range on the
  track; each preferred time is a light-blue bar under it, on the same scale,
  with dashed lines up to the track and its two times under its ends. A bar
  is moved by dragging it, sized by dragging an end, and removed with its ✕;
  the + hanging off the box (as a table's add) puts a new one in the
  window's next free stretch.

  Keyboard: a bar takes focus — ← → move it half an hour, Shift + ← → move
  its end, Delete removes it.

  NEVER OVERLAPPING (Pavan, 2026-10-20) — a bar stops at its neighbours,
  whichever way it is dragged or typed; with no free half hour left in the
  window, + says to delete or adjust one first. PRESS A TIME under a bar to
  type its start and end to the minute — the slider and the box are the same
  value.
*/

const DAY = 24 * 60;
const STEP = 30;
/** Every third hour labelled, as the reference. */
const TICKS = [0, 3, 6, 9, 12, 15, 18, 21, 24];
const pct = (m: number) => `${(m / DAY) * 100}%`;
/** `4a`, `1:30p` — the reference's short times. */
const short = (m: number) => {
  const h24 = Math.floor((((m % DAY) + DAY) % DAY) / 60);
  const mm = m % 60;
  const h = h24 % 12 === 0 ? 12 : h24 % 12;
  return `${h}${mm ? `:${String(mm).padStart(2, "0")}` : ""}${h24 < 12 ? "a" : "p"}`;
};
const hhmm = (m: number) =>
  `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`;
const fromHhmm = (v: string) => {
  const m = v.match(/^(\d{1,2}):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
};
const tick = (h: number) =>
  h === 0 || h === 24
    ? "12a"
    : h === 12
      ? "12p"
      : h < 12
        ? `${h}a`
        : `${h - 12}p`;

type Drag = {
  i: number;
  mode: "move" | "start" | "end";
  grab: number;
  from: TimeSpan;
};

export function DeliveryWindowTimeline({
  start,
  end,
  onWindowChange,
  preferred,
  onPreferredChange,
  disabled,
  required,
  label = "Delivery window & preferred time",
}: {
  /** The field's label, outside the box — every module says it its own way. */
  label?: string;
  /** The delivery window, minutes from midnight. */
  start: number;
  end: number;
  onWindowChange: (start: number, end: number) => void;
  preferred: TimeSpan[];
  onPreferredChange: (next: TimeSpan[]) => void;
  disabled?: boolean;
  required?: boolean;
}) {
  const scale = React.useRef<HTMLDivElement>(null);
  const [width, setWidth] = React.useState(0);
  React.useLayoutEffect(() => {
    if (!scale.current) return;
    const ro = new ResizeObserver(([e]) => setWidth(e.contentRect.width));
    ro.observe(scale.current);
    return () => ro.disconnect();
  }, []);
  const drag = React.useRef<Drag | null>(null);
  /* THE NEW BAR TAKES FOCUS (DS ui §10f) — so ← → move it at once. */
  const [focusNew, setFocusNew] = React.useState<number | null>(null);
  /** The bar whose times are being typed, and which box opened it. */
  const [edit, setEdit] = React.useState<{
    i: number;
    field: "start" | "end";
  } | null>(null);
  const [full, setFull] = React.useState(false);
  React.useEffect(() => setFull(false), [preferred, start, end]);

  /* THE ROOM A BAR HAS — from its neighbours (or the window) either side. */
  const room = (i: number, at: TimeSpan) => {
    const others = preferred.filter((_, j) => j !== i);
    return {
      lo: Math.max(
        start,
        ...others.filter((q) => q.end <= at.start).map((q) => q.end),
      ),
      hi: Math.min(
        end,
        ...others.filter((q) => q.start >= at.end).map((q) => q.start),
      ),
    };
  };

  const toMin = (clientX: number) => {
    const r = scale.current!.getBoundingClientRect();
    return Math.round((((clientX - r.left) / r.width) * DAY) / STEP) * STEP;
  };
  const clampSpan = (
    i: number,
    at: TimeSpan,
    s: number,
    e: number,
    mode: Drag["mode"],
  ): TimeSpan => {
    const { lo, hi } = room(i, at);
    if (mode === "move") {
      const len = e - s;
      const a = Math.min(Math.max(s, lo), hi - len);
      return { start: a, end: a + len };
    }
    if (mode === "start")
      return { start: Math.min(Math.max(s, lo), e - STEP), end: e };
    return { start: s, end: Math.max(Math.min(e, hi), s + STEP) };
  };
  const setAt = (i: number, p: TimeSpan) =>
    onPreferredChange(preferred.map((x, j) => (j === i ? p : x)));

  const onDown = (e: React.PointerEvent, i: number, mode: Drag["mode"]) => {
    if (disabled) return;
    e.preventDefault();
    e.stopPropagation();
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    drag.current = { i, mode, grab: toMin(e.clientX), from: preferred[i] };
  };
  const onMove = (e: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    const delta = toMin(e.clientX) - d.grab;
    const s = d.mode === "end" ? d.from.start : d.from.start + delta;
    const en = d.mode === "start" ? d.from.end : d.from.end + delta;
    setAt(d.i, clampSpan(d.i, d.from, s, en, d.mode));
  };
  const onUp = () => (drag.current = null);

  const add = () => {
    /* THE FIRST FREE STRETCH OF HALF AN HOUR OR MORE, up to two hours. */
    const taken = [...preferred].sort((a, b) => a.start - b.start);
    let at = start;
    for (const q of [...taken, { start: end, end }]) {
      if (q.start - at >= STEP) {
        setFocusNew(preferred.length);
        onPreferredChange([
          ...preferred,
          { start: at, end: Math.min(q.start, at + 120) },
        ]);
        return;
      }
      at = Math.max(at, q.end);
    }
    setFull(true);
  };
  /* A TYPED PAIR — what's wrong with it, or null when it fits. */
  const problem = (i: number, s: number | null, e: number | null) => {
    if (s === null || e === null) return "Enter both times";
    if (e <= s) return "End after the start";
    if (s < start || e > end)
      return `Inside the delivery window, ${formatWindow(start, end)}`;
    if (preferred.some((q, j) => j !== i && s < q.end && e > q.start))
      return "Overlaps another preferred time";
    return null;
  };
  const onKey = (e: React.KeyboardEvent, i: number) => {
    const p = preferred[i];
    const by =
      e.key === "ArrowRight" ? STEP : e.key === "ArrowLeft" ? -STEP : 0;
    if (by) {
      e.preventDefault();
      setAt(
        i,
        e.shiftKey
          ? clampSpan(i, p, p.start, p.end + by, "end")
          : clampSpan(i, p, p.start + by, p.end + by, "move"),
      );
    } else if (e.key === "Delete" || e.key === "Backspace") {
      e.preventDefault();
      onPreferredChange(preferred.filter((_, j) => j !== i));
    }
  };

  const has = preferred.length > 0;
  const canAdd = !disabled && end - start >= STEP;
  return (
    /* THE LABEL OUTSIDE, as every field's (Pavan, 2026-10-20); the unit in
       the input's own outline; the add hangs off its corner, as a table's. */
    <SheetField label={label} required={required}>
      <div className="flex flex-col">
        <div
          className={cn(
            "flex flex-col gap-2 rounded-md border border-input bg-fp-surface-1b px-4 pt-3 pb-3 transition-[color,box-shadow] focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/50 dark:bg-fp-field-fill",
            canAdd && "rounded-bl-none",
          )}
        >
          <div className="flex min-w-0 items-baseline justify-between gap-3">
            <span className="text-sm whitespace-nowrap tabular-nums text-foreground">
              {formatWindow(start, end)}
            </span>
            <span className="min-w-0 truncate text-xs text-muted-foreground">
              {formatSpan(start, end)}
            </span>
          </div>

          {/* THE SCALE — track, hours, then the preferred bars on the same day. */}
          <div
            ref={scale}
            className={cn("relative", has ? "h-[78px]" : "h-10")}
            onPointerMove={onMove}
            onPointerUp={onUp}
          >
            <Slider
              className="absolute inset-x-0 top-0 h-5 [&_[data-slot=slider-thumb]]:size-5 [&_[data-slot=slider-track]]:h-2.5"
              aria-label="Delivery window"
              min={0}
              max={DAY}
              step={STEP}
              minStepsBetweenThumbs={60 / STEP}
              value={[start, end]}
              disabled={disabled}
              onValueChange={([a, b]) => onWindowChange(a, b)}
            />
            <div
              aria-hidden
              className="absolute inset-x-0 top-6 h-3.5 select-none"
            >
              {TICKS.map((h, i) => (
                <span
                  key={h}
                  className={cn(
                    "absolute top-0 text-xs leading-none tabular-nums text-muted-foreground",
                    i === 0 && "left-0",
                    i === TICKS.length - 1 && "right-0",
                    i > 0 && i < TICKS.length - 1 && "-translate-x-1/2",
                  )}
                  style={
                    i === 0 || i === TICKS.length - 1
                      ? undefined
                      : { left: `${(h / 24) * 100}%` }
                  }
                >
                  {tick(h)}
                </span>
              ))}
            </div>

            {preferred.map((p, i) => {
              /* A NARROW BAR PUTS ITS TIMES OUTSIDE ITS ENDS, so they never meet. */
              const narrow =
                width > 0 && ((p.end - p.start) / DAY) * width < 84;
              /* WHERE TWO BARS MEET, THE TIME IS PRINTED ONCE — by the later bar. */
              const shared = preferred.some(
                (q, j) => j !== i && q.start === p.end,
              );
              return (
                <React.Fragment key={i}>
                  {[p.start, p.end].map((m, k) => (
                    <span
                      key={k}
                      aria-hidden
                      className="absolute top-4 h-7 border-l border-dashed border-muted-foreground/60"
                      style={{ left: pct(m) }}
                    />
                  ))}
                  <div
                    role="group"
                    ref={(el) => {
                      if (el && i === focusNew) {
                        el.focus({ preventScroll: true });
                        setFocusNew(null);
                      }
                    }}
                    autoFocus={i === focusNew}
                    tabIndex={disabled ? -1 : 0}
                    aria-label={`Preferred time ${formatWindow(p.start, p.end)}`}
                    onKeyDown={(e) => !disabled && onKey(e, i)}
                    onPointerDown={(e) => onDown(e, i, "move")}
                    className={cn(
                      "group/bar absolute top-11 h-2.5 rounded-xs bg-fp-lane-blue/30 outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
                      !disabled &&
                        "cursor-grab active:cursor-grabbing hover:bg-fp-lane-blue/45",
                    )}
                    /* 1px of air each side, so two bars that meet stay two. */
                    style={{
                      left: `calc(${pct(p.start)} + 1px)`,
                      width: `calc(${pct(p.end - p.start)} - 2px)`,
                    }}
                  >
                    {!disabled && (
                      <>
                        {/* THE ENDS SIZE IT — a grip wider than the line. */}
                        <span
                          onPointerDown={(e) => onDown(e, i, "start")}
                          className="absolute inset-y-[-4px] -left-1.5 w-3 cursor-ew-resize"
                        />
                        <span
                          onPointerDown={(e) => onDown(e, i, "end")}
                          className="absolute inset-y-[-4px] -right-1.5 w-3 cursor-ew-resize"
                        />
                        <button
                          type="button"
                          aria-label={`Remove preferred time ${formatWindow(p.start, p.end)}`}
                          onPointerDown={(e) => e.stopPropagation()}
                          onClick={() =>
                            onPreferredChange(
                              preferred.filter((_, j) => j !== i),
                            )
                          }
                          className="absolute top-1/2 -right-6 flex size-5 -translate-y-1/2 items-center justify-center rounded-sm text-muted-foreground opacity-0 outline-none transition-opacity group-hover/bar:opacity-100 group-focus-visible/bar:opacity-100 hover:text-foreground focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
                        >
                          <X className="size-3.5" />
                        </button>
                      </>
                    )}
                  </div>
                  {/* A SHORT BAR CARRIES ONE LABEL, BOTH TIMES — two would run
                      into each other or into the next bar's. */}
                  <TimeLabel
                    m={p.start}
                    text={
                      narrow && !shared
                        ? `${short(p.start)}–${short(p.end)}`
                        : undefined
                    }
                    open={edit?.i === i && edit.field === "start"}
                    onOpenChange={(o) =>
                      setEdit(o ? { i, field: "start" } : null)
                    }
                    disabled={disabled}
                  >
                    <TimesEditor
                      p={p}
                      focus="start"
                      check={(a, b) => problem(i, a, b)}
                      onCommit={(np) => setAt(i, np)}
                    />
                  </TimeLabel>
                  {!shared && !narrow && (
                    <TimeLabel
                      m={p.end}
                      className="-translate-x-full"
                      open={edit?.i === i && edit.field === "end"}
                      onOpenChange={(o) =>
                        setEdit(o ? { i, field: "end" } : null)
                      }
                      disabled={disabled}
                    >
                      <TimesEditor
                        p={p}
                        focus="end"
                        check={(a, b) => problem(i, a, b)}
                        onCommit={(np) => setAt(i, np)}
                      />
                    </TimeLabel>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>
        <div className="flex items-start gap-3">
          {canAdd && <HangingAdd label="Add preferred time" onClick={add} />}
          {/* NO ROOM LEFT (Pavan, 2026-10-20) — said where the add was pressed. */}
          {full && (
            <p
              role="alert"
              className="flex items-center gap-1.5 pt-1.5 text-xs text-status-failed"
            >
              <TriangleAlert className="size-3.5 shrink-0" />
              Delete or adjust the current preferred time to add a new one.
            </p>
          )}
        </div>
      </div>
    </SheetField>
  );
}

/** A bar's time under its end — pressed, it opens the typed times. */
function TimeLabel({
  m,
  text,
  className,
  open,
  onOpenChange,
  disabled,
  children,
}: {
  m: number;
  /** In place of the one time — a short bar's "8a–9:20a". */
  text?: string;
  className?: string;
  open: boolean;
  onOpenChange: (o: boolean) => void;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  const label = (
    <span
      className={cn(
        "absolute top-[59px] text-xs leading-none tabular-nums text-foreground",
        className,
      )}
      style={{ left: pct(m) }}
    >
      {text ?? short(m)}
    </span>
  );
  if (disabled) return label;
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={`Type the preferred time, ${short(m)}`}
          className={cn(
            "absolute top-[57px] -ml-0.5 rounded-sm px-0.5 py-0.5 text-xs leading-none tabular-nums text-foreground underline decoration-current/40 decoration-dotted underline-offset-2 outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50",
            className,
          )}
          style={{ left: pct(m) }}
        >
          {text ?? short(m)}
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto p-3">
        {children}
      </PopoverContent>
    </Popover>
  );
}

/** START AND END TO THE MINUTE — each change that fits is kept at once. */
function TimesEditor({
  p,
  focus,
  check,
  onCommit,
}: {
  p: TimeSpan;
  focus: "start" | "end";
  check: (s: number | null, e: number | null) => string | null;
  onCommit: (p: TimeSpan) => void;
}) {
  const [a, setA] = React.useState(hhmm(p.start));
  const [b, setB] = React.useState(hhmm(p.end));
  const err = check(fromHhmm(a), fromHhmm(b));
  const put = (na: string, nb: string) => {
    const s = fromHhmm(na);
    const e = fromHhmm(nb);
    if (!check(s, e)) onCommit({ start: s!, end: e! });
  };
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-end gap-2">
        <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground">
          Start
          <Input
            type="time"
            step={60}
            className="w-[130px]"
            value={a}
            autoFocus={focus === "start"}
            onChange={(e) => {
              setA(e.target.value);
              put(e.target.value, b);
            }}
          />
        </label>
        <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground">
          End
          <Input
            type="time"
            step={60}
            className="w-[130px]"
            value={b}
            autoFocus={focus === "end"}
            onChange={(e) => {
              setB(e.target.value);
              put(a, e.target.value);
            }}
          />
        </label>
      </div>
      {err && <p className="text-xs text-status-failed">{err}</p>}
    </div>
  );
}

import { Download, Upload } from "lucide-react";
import { Button } from "@/components/ui/button";
import { FileTypeIcon } from "@/components/ui/file-type-icon";

/*
  THE DOCUMENTS TABLE — one for every record that keeps files (3PL Delivery
  Orders, the portal's order requests and invoice disputes). The 3PL
  anatomy, which is the source of truth (Pavan, 2026-10-14):

    Document (its format icon, then the name) · Added · By · ↓
    (No Kind column — Pavan, 2026-10-14: the format icon says what it is.)

  ALWAYS A TABLE, AND NEVER EMPTY OF ROWS. With nothing uploaded it still
  holds one row (Pavan, 2026-10-14): where the reader can add, that row IS
  the upload — press it to pick files; where they cannot, it says what will
  arrive. The section never changes shape when the first file lands.
*/

export interface DocumentRow {
  id: string;
  kind: string;
  name: string;
  /** Already formatted for reading. */
  added: string;
  by: string;
}

export function DocumentsTable({
  rows,
  onAdd,
  emptyText = "No documents yet.",
  onDownload,
}: {
  rows: DocumentRow[];
  /** Given, the empty row is an upload slot. */
  onAdd?: () => void;
  /** The empty row's words when there is no upload here. */
  emptyText?: string;
  onDownload?: (row: DocumentRow) => void;
}) {
  return (
    <table className="w-full table-fixed text-sm">
      <colgroup>
        <col />
        <col className="w-[18%]" />
        <col className="w-[20%]" />
        <col className="w-12" />
      </colgroup>
      <thead>
        <tr className="border-b border-border bg-fp-table-header">
          {["Document", "Added", "By"].map((h) => (
            <th key={h} className="px-3 py-2 text-left text-xs font-medium text-muted-foreground">
              {h}
            </th>
          ))}
          <th className="w-10 px-3 py-2" />
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 &&
          (onAdd ? (
            /* THE EMPTY ROW IS THE UPLOAD. */
            <tr className="h-12 cursor-pointer border-b border-border last:border-0 hover:bg-fp-row-hover" onClick={onAdd}>
              <td className="px-3">
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onAdd();
                  }}
                  className="flex items-center gap-2 rounded-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                >
                  <Upload className="size-4" />
                  Upload a document
                </button>
              </td>
              <td className="px-3 text-muted-foreground">—</td>
              <td className="px-3 text-muted-foreground">—</td>
              <td />
            </tr>
          ) : (
            <tr className="h-12">
              <td colSpan={4} className="px-3 text-muted-foreground">
                {emptyText}
              </td>
            </tr>
          ))}
        {rows.map((doc) => (
          <tr key={doc.id} className="h-12 border-b border-border last:border-0">
            <td className="px-3">
              <span className="flex min-w-0 items-center gap-2.5">
                <FileTypeIcon name={doc.name} />
                <span className="truncate text-foreground" title={doc.name}>
                  {doc.name}
                </span>
              </span>
            </td>
            <td className="truncate px-3 text-muted-foreground">{doc.added}</td>
            <td className="truncate px-3 text-muted-foreground">{doc.by}</td>
            <td className="px-2">
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={`Download ${doc.name}`}
                className="text-muted-foreground"
                onClick={() => onDownload?.(doc)}
              >
                <Download />
              </Button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

import * as React from "react";
import { Plus } from "lucide-react";
import { cn } from "@/lib/utils";

/*
  THE ADD ON A TABLE — a tab hanging off the card's bottom-left corner.

  WHY NOT A BAND INSIDE THE CARD. A full-width strip draws a rule across the
  whole card to carry one small act, and what it reads as is an empty extra
  row of the table. (Pavan, 2026-09-22 — after both were built and put side by
  side.)

  WHY FILLED AND NOT OUTLINED. It takes the table's own header tint, so it
  continues the table rather than sitting near it as a separate control. An
  outline would be a second box under a card that already has one, which is
  the nesting `docs/ds/ui/2-rules.md` §10f exists to remove.

  A PLUS, AND THE WORDS ON HOVER. The row it adds is one of many and the sign
  says the act; a permanent label makes an ordinary add look like the
  section's main one. The label still arrives on keyboard focus, so it is not
  a thing only a mouse can find, and the button keeps its `aria-label` either
  way — the collapsed state is a visual economy, never a nameless control.
*/

/* IT CAN OPEN A MENU (Pavan, 2026-10-07). When one add offers a choice of
   row — the quote's Fee or Tax — it is a menu's trigger, so whatever the
   trigger hands it (ref, pointer and key handlers, aria) is passed through.
   Nothing about how it looks changes. */
export function HangingAdd({
  label,
  onClick,
  disabled,
  className,
  ...trigger
}: {
  /** "Add products", "Add vendor" — the table's own noun, always plural-safe. */
  label: string;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  disabled?: boolean;
  className?: string;
} & Omit<React.ComponentPropsWithRef<"button">, "onClick" | "className" | "disabled">) {
  const [open, setOpen] = React.useState(false);

  return (
    <button
      {...trigger}
      type="button"
      aria-label={label}
      disabled={disabled}
      onClick={onClick}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onBlur={() => setOpen(false)}
      className={cn(
        /* SQUARE ON TOP, ROUNDED BELOW — the top edge is the card's bottom
           edge, and a radius there would show a notch between them. */
        "flex h-8 items-center rounded-t-none rounded-b-md bg-fp-table-header px-2.5",
        "text-sm font-medium text-foreground outline-none transition-colors",
        "hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50",
        "disabled:pointer-events-none disabled:opacity-50",
        className
      )}
    >
      <Plus className="size-4 shrink-0" />
      <span
        className={cn(
          "overflow-hidden whitespace-nowrap transition-[max-width,opacity,padding] duration-200",
          open ? "max-w-[140px] pl-1.5 opacity-100" : "max-w-0 opacity-0"
        )}
      >
        {label}
      </span>
    </button>
  );
}

import * as React from "react";
import { ArrowDown, ArrowUp, ChevronRight, ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { useA11y } from "@/components/theme/a11y";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { OverflowChip, type BreakdownRow } from "./BreakdownCard";
import {
  GroupHeaderRow,
  TableColumnHeader,
  useTableColumns,
  type GroupNode,
} from "@/components/tables-layout";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

/**
 * Generic list table — the chrome only, with cells supplied by the caller.
 *
 * The chrome is the DS DataTable's (Figma 28165:3758) and is copied from
 * FuelOrdersTable rather than re-derived, so the three lists are identical
 * where they should be: outer stroke on `border`, sticky Surface-1a header with
 * a bottom hairline so rows scroll under it, 40px header row, 56px body rows,
 * px-3 cells, the asc → desc → unsorted sort glyph cycle, and a pinned trailing
 * actions column whose opaque fill re-applies the row's hover/selected tint as a
 * `before` overlay (otherwise the pinned cell hides it).
 *
 * FuelOrdersTable is deliberately NOT refactored onto this. Its Product and Tags
 * cells carry measured-width truncation with a ResizeObserver, which nothing
 * else needs; moving it would be churn without benefit. This exists so Asset
 * Orders and Customers do not each re-copy the chrome a third and fourth time.
 *
 * DS FOLLOW-UP: this shell, `TwoLineCell` and `OverflowBadge` are not
 * screen-specific. They belong beside `tables-layout/DataTable` once the DS
 * version can take a column set and a cell renderer as props.
 */

/** A value that reads as one thing — a record number or code (no spaces),
    or a date ("Oct 23, 2026"). */
const ONE_LINE = /^(\S+|[A-Z][a-z]{2} \d{1,2}, \d{4})$/;

export interface ListColumn<K extends string> {
  key: K;
  label: string;
  width: number;
  sortable?: boolean;
  /**
   * `right` for money and for counts that are compared down the column —
   * the digits line up and the eye reads magnitude without reading numbers.
   * `center` for a short count that is READ rather than compared, where a
   * right edge miles from the header looks like a mistake.
   */
  align?: "left" | "right" | "center";
}

export interface ListSort<K extends string> {
  key: K;
  dir: "asc" | "desc";
}

export interface ListTableProps<Row, K extends string> {
  /** A ROW ABOVE THE HEADER, inside the table's frame and outside its scroll —
   *  for the table's own tools (see `ListToolbarProps.tableToolsInto`). */
  topBar?: React.ReactNode;
  /** Every cell sits at the top of its row — for rows that grow tall with
   *  stacked lines, so the record's own cells read first. */
  alignTop?: boolean;
  rows: Row[];
  columns: ListColumn<K>[];
  hidden?: Set<K>;
  sort: ListSort<K> | null;
  onSort: (key: K) => void;
  /** Stable identity for the React key. */
  rowId: (row: Row) => string;
  /** Cell content per column. `actions` is supplied by this component. */
  renderCell: (row: Row, key: K) => React.ReactNode;
  /** Opens the row's side sheet, via the pinned chevron. */
  onOpenRow?: (row: Row) => void;
  /** Accessible label for that chevron, e.g. `Open order 4592866`. */
  openLabel: (row: Row) => string;
  /** Which column key holds the pinned chevron. */
  actionsKey: K;
  /**
   * SELECTION IS OPT-IN. A list with nothing to do to a selection should not
   * spend 44px on a checkbox column that leads nowhere, so the column exists
   * only when the handlers for it do — the same rule the bulk bar follows.
   */
  selectedIds?: ReadonlySet<string>;
  onToggleRow?: (id: string) => void;
  /** `next` is the state the header checkbox is moving TO, so the caller does
   *  not have to re-derive it from the current selection. */
  onToggleAll?: (next: boolean) => void;
  /**
   * Skeleton rows in place of content. Not a spinner: a list that collapses to
   * a spinner loses its own height, and the page jumps when the rows land.
   */
  loading?: boolean;
  skeletonRows?: number;
  /**
   * Column order, as keys. Supply with `onReorderColumns` to keep it in a saved
   * view; leave both off and the table remembers it for the session only. The
   * pinned chevron column never moves.
   */
  columnOrder?: string[];
  onReorderColumns?: (next: string[]) => void;
  /** Reader-set column widths in px, by key. Same dual-mode as the order. */
  columnWidths?: Record<string, number>;
  onResizeColumns?: (next: Record<string, number>) => void;
  /**
   * Grouped render list from `groupRows`. Omitted, the table renders `rows`
   * flat — which is what every ungrouped list does.
   */
  nodes?: GroupNode<Row>[];
  collapsedGroups?: ReadonlySet<string>;
  onToggleGroupCollapse?: (id: string) => void;
  /**
   * A BOX PER COLUMN, UNDER THE HEADERS.
   *
   * The question "where is the Halvorsen order" is asked OF a column, so it is
   * answered at the column. A single search box asks it of the whole row and
   * brings back everything that mentions the word anywhere; a popover that
   * searches one named column asks it properly but only once, so two
   * conditions meant two searches and remembering the first.
   *
   * The boxes are AND-ed, because that is what typing in two of them looks
   * like it should do. The row only exists while the reader has asked for it —
   * see `ListToolbarProps.onToggleColumnFilters` — because 40px of empty
   * inputs above every table is a permanent cost for an occasional question.
   */
  columnFilters?: Record<string, string>;
  onColumnFilterChange?: (key: K, value: string) => void;
  showColumnFilters?: boolean;
  /** What one record is called in a group header — "asset", "account". */
  groupNoun?: string;
  /** Unit for the summed measure the headers carry, e.g. `gal`. */
  groupUnit?: string;
  /**
   * A NESTED LAYER — the DS expandable row (`tables-layout/DataTable`,
   * Pavan, 2026-10-17). Given, the first column's cell leads with a small
   * chevron that turns down and opens this content in a full-width row
   * beneath: pinned to the visible width, WHITE (the content layer), and a
   * 2px GREEN rail that runs unbroken from the parent row's left edge into
   * it. The open parent keeps a tint and drops its bottom divider (DS ui
   * §10j).
   */
  renderExpanded?: (row: Row) => React.ReactNode;
  /** The chevron's label, e.g. `Show tanks for REQ-1115`. */
  expandLabel?: (row: Row, open: boolean) => string;
}

export function ListTable<Row, K extends string>({
  rows,
  columns,
  hidden,
  sort,
  onSort,
  rowId,
  renderCell,
  onOpenRow,
  openLabel,
  actionsKey,
  selectedIds,
  onToggleRow,
  onToggleAll,
  loading = false,
  skeletonRows = 10,
  nodes,
  collapsedGroups,
  onToggleGroupCollapse,
  groupNoun = "record",
  groupUnit = "",
  columnOrder,
  onReorderColumns,
  columnWidths,
  onResizeColumns,
  columnFilters,
  onColumnFilterChange,
  showColumnFilters = false,
  renderExpanded,
  expandLabel,
  alignTop = false,
  topBar,
}: ListTableProps<Row, K>) {
  const expandable = Boolean(renderExpanded);
  const [expanded, setExpanded] = React.useState<ReadonlySet<string>>(() => new Set());
  const toggleExpand = (id: string) =>
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  /* THE FRAME'S WIDTH — what the columns fill, and what a nested layer
     spans (the visible width, not the scrolled one). */
  const frame = React.useRef<HTMLDivElement>(null);
  const [frameWidth, setFrameWidth] = React.useState<number | undefined>();
  React.useEffect(() => {
    if (!frame.current) return;
    const el = frame.current;
    const ro = new ResizeObserver(() => setFrameWidth(el.clientWidth));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  /* THE PINNED CHEVRON IS THE FRAME, not a column: it is how a row is opened
     and it is stuck to the right edge so it survives a sideways scroll. It
     does not move, and nothing can be dropped past it. */
  /* Columns move and resize because the DS header does it — see
     `useTableColumns`. Nothing here but which column is structure. */
  const cols = useTableColumns({
    keys: React.useMemo(() => columns.map((c) => c.key), [columns]),
    fixed: React.useMemo(() => [actionsKey], [actionsKey]),
    order: columnOrder,
    onOrderChange: onReorderColumns,
    widths: columnWidths,
    onWidthsChange: onResizeColumns,
  });
  /* NO CHEVRON COLUMN (Pavan, 2026-10-19): the row itself opens the
     record — a click anywhere on it, or Enter on a focused row — so the
     pinned chevron cell at the end is gone from every list. `actionsKey`
     names that column so it is dropped here. */
  const visible = cols.arrange(columns.filter((c) => !hidden?.has(c.key) && c.key !== actionsKey));

  /* THE CHECKBOX COLUMN IS NOT A COLUMN. It cannot be hidden, reordered,
     resized or sorted, so it sits outside `cols` entirely and is drawn as a
     fixed 44px cell at the head of every row — the mirror of the pinned
     chevron at the tail. */
  const selectable = Boolean(selectedIds && onToggleRow);
  const ids = rows.map(rowId);
  const allSelected = selectable && ids.length > 0 && ids.every((id) => selectedIds!.has(id));
  const someSelected = selectable && ids.some((id) => selectedIds!.has(id));
  const span = visible.length + (selectable ? 1 : 0);
  /* NO EMPTY SPACE ON THE RIGHT, EVER (Pavan, 2026-10-22). Each column starts
     at the width its longest value needs (DS ui §10p); when the table is
     narrower than its frame, the spare width goes to the columns that hold
     the most — a column gets a share in proportion to how far it is wider
     than 120px, so an icon, a count or a short code stays as it is and a
     name, an address or a contact takes the room. Wider than the frame, the
     table scrolls. */
  /* RECORD NUMBERS AND DATES STAY ON ONE LINE (Pavan, 2026-10-23). At a
     bigger Text size the other cells wrap inside their column, but a value
     like "D-105370" or "Oct 23, 2026" broken in two stops reading as one, so
     its column widens by exactly what the value lacks. Measured after paint;
     it only ever grows while the text size holds, so it can't see-saw. */
  const textSize = useA11y().text;
  const [oneLine, setOneLine] = React.useState<{ at: number; need: Record<string, number> }>({ at: 0, need: {} });
  const need = oneLine.at === textSize ? oneLine.need : {};
  React.useLayoutEffect(() => {
    const root = frame.current;
    if (!root || textSize === 0) return;
    const lead = selectedIds && onToggleRow ? 1 : 0;
    const next: Record<string, number> = { ...need };
    let grew = false;
    root.querySelectorAll<HTMLTableRowElement>("tbody tr").forEach((tr) => {
      if (tr.children.length !== visible.length + lead) return;
      visible.forEach((c, i) => {
        const td = tr.children[i + lead] as HTMLElement;
        td.querySelectorAll<HTMLElement>(".truncate").forEach((el) => {
          if (!ONE_LINE.test(el.textContent?.trim() ?? "")) return;
          el.dataset.oneLine = "";
          const short = el.scrollWidth - el.clientWidth;
          if (short <= 1) return;
          const want = Math.ceil(td.offsetWidth + short);
          if (want > (next[c.key] ?? 0)) {
            next[c.key] = want;
            grew = true;
          }
        });
      });
    });
    if (grew || oneLine.at !== textSize) setOneLine({ at: textSize, need: next });
    /* Re-measured when the text size, the rows or the columns change. */
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [textSize, rows, frameWidth, visible.map((c) => c.key).join(), oneLine]);
  const base = visible.map((c) => Math.max(cols.widthOf(c), need[c.key] ?? 0));
  const widths = (() => {
    const lead = selectable ? 44 : 0;
    const spare = (frameWidth ?? 0) - lead - base.reduce((a, b) => a + b, 0);
    if (spare <= 0) return base;
    const weight = base.map((w) => Math.max(0, w - 120));
    const total = weight.reduce((a, b) => a + b, 0) || base.reduce((a, b) => a + b, 0);
    const share = total === 0 ? base.map(() => 0) : (weight.some((w) => w > 0) ? weight : base).map((w) => w / total);
    const out = base.map((w, i) => Math.floor(w + spare * share[i]));
    /* What rounding left goes on the widest column, so the edge lands exactly. */
    const left = (frameWidth ?? 0) - lead - out.reduce((a, b) => a + b, 0);
    const widest = out.indexOf(Math.max(...out));
    if (widest >= 0) out[widest] += Math.max(0, left);
    return out;
  })();

  const body = (
    <div
      ref={frame}
      className={cn(
        "overflow-auto [&_[data-slot=table-container]]:overflow-visible",
        topBar ? "min-h-0 flex-1" : "h-full rounded-md border border-border"
      )}
    >
      <Table style={{ tableLayout: "fixed", width: widths.reduce((a, b) => a + b, selectable ? 44 : 0) }}>
        <colgroup>
          {selectable && <col style={{ width: "44px" }} />}
          {visible.map((c, i) => (
            <col key={c.key} style={{ width: `${widths[i]}px` }} />
          ))}
        </colgroup>
        <TableHeader className="sticky top-0 z-20">
          <TableRow className="h-10">
            {selectable && (
              <TableHead className="border-b border-fp-outline-1 bg-fp-table-header px-3">
                <Checkbox
                  checked={allSelected ? true : someSelected ? "indeterminate" : false}
                  onCheckedChange={() => onToggleAll?.(!allSelected)}
                  aria-label={allSelected ? "Clear selection" : "Select all rows on this page"}
                />
              </TableHead>
            )}
            {visible.map((col) => {
              const active = sort?.key === col.key;
              /* THE SORTED COLUMN (Pavan, 2026-10-21): a real arrow, not a
                 chevron, on a darker grey header; its cells a very light grey. */
              const SortIcon = !active
                ? ChevronsUpDown
                : sort.dir === "asc"
                  ? ArrowUp
                  : ArrowDown;
              return (
                <TableColumnHeader
                  key={col.key}
                  cols={cols}
                  col={col}
                  aria-sort={
                    active
                      ? sort.dir === "asc"
                        ? "ascending"
                        : "descending"
                      : undefined
                  }
                  className={cn(
                    "border-b border-fp-outline-1 bg-fp-table-header px-3 text-xs font-medium text-muted-foreground",
                    col.key === actionsKey && "sticky right-0 z-30"
                  )}
                >
                  {col.label && col.sortable ? (
                    <button
                      type="button"
                      onClick={() => onSort(col.key)}
                      aria-label={`Sort by ${col.label}`}
                      className={cn(
                        "inline-flex items-center gap-1 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50",
                        active && "text-foreground"
                      )}
                    >
                      {col.label}
                      <SortIcon
                        className={cn(
                          "size-3.5",
                          active ? "opacity-100" : "opacity-50"
                        )}
                      />
                    </button>
                  ) : col.label ? (
                    <span>{col.label}</span>
                  ) : null}
                </TableColumnHeader>
              );
            })}
          </TableRow>
          {showColumnFilters && onColumnFilterChange && (
            /* THE SECOND HEADER ROW, not a first body row: it scrolls and
               sticks with the headers it belongs to, and the table's own
               `<thead>` is what tells a screen reader these are not records. */
            /* THE BAND IS QUIETER THAN THE HEADER IT SITS UNDER. At the same
               fill the two read as one 80px header, and the boxes looked like
               part of the column names rather than something you do to them.
               On the content layer's own surface the strip recedes and the
               inputs are the only thing in it with an edge — which is right,
               because they are the only thing in it you can touch. */
            <TableRow className="h-11 hover:bg-transparent">
              {selectable && (
                <TableHead className="border-b border-fp-outline-1 bg-fp-surface-1b px-3" />
              )}
              {visible.map((col) => (
                <TableHead
                  key={col.key}
                  className={cn(
                    "border-b border-fp-outline-1 bg-fp-surface-1b px-2",
                    col.key === actionsKey && "sticky right-0 z-30"
                  )}
                >
                  {col.label ? (
                    <Input
                      value={columnFilters?.[col.key] ?? ""}
                      onChange={(e) => onColumnFilterChange(col.key, e.target.value)}
                      /* THE PLACEHOLDER GOES WHERE IT WOULD BE CUT. A column
                         narrow enough to clip the word shows an empty box
                         instead — "Filte" reads as a bug, and the row of
                         identical boxes has already said what they are. */
                      placeholder={(columnWidths?.[col.key] ?? col.width) >= 96 ? "Filter…" : ""}
                      aria-label={`Filter by ${col.label}`}
                      /* `data-no-row-open` keeps a click in the box from being
                         read as a click on the row it sits above. */
                      data-no-row-open
                      /* `rounded-md` and no shadow — the DS's field shape.
                         A pill is the chip vocabulary, and a raised field in a
                         strip of fields lifts a row of boxes off a surface
                         they belong to. */
                      className="h-7 rounded-md px-2.5 text-xs shadow-none"
                    />
                  ) : null}
                </TableHead>
              ))}
            </TableRow>
          )}
        </TableHeader>
        <TableBody>
          {loading
            ? Array.from({ length: skeletonRows }, (_, i) => (
                <TableRow key={`sk-${i}`} className="h-14">
                  {selectable && (
                    <TableCell className="px-3">
                      <Skeleton className="size-4 rounded-[4px]" />
                    </TableCell>
                  )}
                  {visible.map((col) => (
                    <TableCell key={col.key} className="px-3">
                      {col.key === actionsKey ? null : (
                        <Skeleton
                          className="h-4"
                          /* Widths vary per column and per row so the block
                             reads as text arriving, not as a loading bar. */
                          style={{ width: `${45 + ((i * 17 + col.key.length * 11) % 45)}%` }}
                        />
                      )}
                    </TableCell>
                  ))}

                </TableRow>
              ))
            : (nodes ??
            rows.map((row) => ({
              kind: "row" as const,
              id: rowId(row),
              depth: 0,
              row,
            }))
          ).map((node) =>
            node.kind === "group" ? (
              <GroupHeaderRow
                key={node.id}
                colSpan={span}
                depth={node.depth}
                label={node.label}
                dimLabel={node.dimLabel}
                count={node.count}
                measure={node.measure}
                unit={groupUnit}
                noun={groupNoun}
                collapsed={Boolean(collapsedGroups?.has(node.id))}
                onToggle={() => onToggleGroupCollapse?.(node.id)}
              />
            ) : (
            /* THE WHOLE ROW OPENS THE RECORD.
               The chevron stays — it is where the eye goes to learn that a row
               CAN be opened, and it is the only part of a 1,400px row a
               keyboard can reach. But making it the only target means a reader
               who has just finished reading a row at the far left has to travel
               the width of the table to act on what they read, and clicking the
               row is what everybody tries first anyway.

               CLICKS THAT LAND ON SOMETHING ELSE ARE NOT ROW CLICKS. A
               checkbox, the chevron, a link inside a cell — each is its own
               act, and an ancestor handler that fired as well would make one
               press do two things. `closest` on the real target is how the row
               tells the difference; a text selection dragged across a cell is
               not a click either. */
            <React.Fragment key={node.id}>
            <TableRow
              className={cn(
                "group/row h-14",
                onOpenRow && "cursor-pointer outline-none focus-visible:bg-fp-row-hover focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
                /* The open parent keeps a tint and drops its divider, so the
                   rail runs on into its layer (DS). */
                expanded.has(node.id) && "border-b-0 bg-fp-row-hover hover:bg-fp-row-hover"
              )}
              data-state={selectedIds?.has(node.id) ? "selected" : undefined}
              data-expanded={expanded.has(node.id) ? "true" : undefined}
              /* THE ROW IS THE CONTROL — reachable by keyboard, Enter or
                 Space opens it, and it says what it opens. */
              tabIndex={onOpenRow ? 0 : undefined}
              aria-label={onOpenRow ? openLabel(node.row) : undefined}
              onKeyDown={(e) => {
                if (!onOpenRow || e.target !== e.currentTarget) return;
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  onOpenRow(node.row);
                }
              }}
              onClick={(e) => {
                if (!onOpenRow) return;
                const t = e.target as HTMLElement | null;
                if (t?.closest("button,a,input,label,[role='checkbox'],[data-no-row-open]"))
                  return;
                if (window.getSelection()?.toString()) return;
                onOpenRow(node.row);
              }}
            >
              {selectable && (
                <TableCell className={cn("px-3", expanded.has(node.id) && "relative before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70")}>
                  <Checkbox
                    checked={selectedIds!.has(node.id)}
                    onCheckedChange={() => onToggleRow!(node.id)}
                    aria-label={`Select ${openLabel(node.row).replace(/^Open /, "")}`}
                  />
                </TableCell>
              )}
              {visible.map((col, ci) => (
                <TableCell
                  key={col.key}
                  className={cn(
                    "px-3",
                    alignTop && "align-top py-3",
                    /* THE RAIL STARTS ON THE OPEN PARENT'S FIRST CELL. */
                    ci === 0 && !selectable && expanded.has(node.id) && "relative before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70",
                    sort?.key === col.key && "fp-sorted-cell",
                    col.key === actionsKey &&
                      /* THE PINNED CELL WEARS THE ROW'S STATE — hover, an open
                         nested layer, selection — so it never reads as a
                         white box at the end of a tinted row. */
                      "sticky right-0 z-10 bg-fp-surface-1b before:pointer-events-none before:absolute before:inset-0 group-hover/row:before:bg-fp-row-hover group-data-[expanded=true]/row:before:bg-fp-row-hover group-data-[state=selected]/row:before:bg-fp-row-selected"
                  )}
                >
                  <span className={cn(col.key === actionsKey && "relative")}>
                    {col.key === actionsKey ? (
                      <div className="flex justify-end">
                        <Button
                          variant="ghost"
                          size="icon-sm"
                          aria-label={openLabel(node.row)}
                          onClick={() => onOpenRow?.(node.row)}
                        >
                          <ChevronRight />
                        </Button>
                      </div>
                    ) : expandable && ci === 0 ? (
                      /* THE CHEVRON LEADS THE FIRST CELL (DS) — not a column. */
                      <span className="flex min-w-0 items-center gap-1.5">
                        <button
                          type="button"
                          onClick={() => toggleExpand(node.id)}
                          aria-expanded={expanded.has(node.id)}
                          aria-label={expandLabel?.(node.row, expanded.has(node.id)) ?? (expanded.has(node.id) ? "Collapse row" : "Expand row")}
                          className="-ml-1 shrink-0 rounded p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                        >
                          <ChevronRight className={cn("size-4 transition-transform", expanded.has(node.id) && "rotate-90")} />
                        </button>
                        <span className="min-w-0">{renderCell(node.row, col.key)}</span>
                      </span>
                    ) : (
                      renderCell(node.row, col.key)
                    )}
                  </span>
                </TableCell>
              ))}

            </TableRow>
            {expandable && expanded.has(node.id) && (
              <TableRow className="hover:bg-transparent data-[state=selected]:bg-transparent">
                {/* THE LAYER IS WHITE (the content layer), end to end, pinned to
                    the visible width so its columns stay put. Its rail is the
                    parent's — the same 2px strip at the same left edge, so the
                    two meet without a step (Pavan, 2026-10-17). */}
                <TableCell colSpan={span} className="bg-fp-surface-1b p-0">
                  <div className="sticky left-0 bg-fp-surface-1b before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70" style={{ width: frameWidth }}>
                    {renderExpanded!(node.row)}
                  </div>
                </TableCell>
              </TableRow>
            )}
            </React.Fragment>
              )
            )}
        </TableBody>
      </Table>
    </div>
  );
  if (!topBar) return body;
  return (
    <div className="flex h-full flex-col overflow-hidden rounded-md border border-border">
      <div className="shrink-0 border-b border-fp-outline-1 bg-fp-surface-1b">{topBar}</div>
      {body}
    </div>
  );
}

/** Primary over a muted secondary — the DS two-line cell. */
/**
 * THE PART OF THE CELL THAT ANSWERED THE FILTER, marked.
 *
 * Reordering the cell so the matched value comes first says WHICH value; this
 * says which part of it. On a column of near-identical names — Clear Diesel #2
 * beside Dyed Diesel — "dies" fetches both and the eye still has to work out
 * what it typed. A mark puts the answer where the question was asked.
 *
 * THE BRAND, AT A QUARTER. The DS binds no meaning to a colour until a usage
 * rule does, and this is the rule: brand is already "the thing you have
 * pointed at" — the active tab, the primary act — and a search match is the
 * same claim about a word. A quarter keeps it a tint under body text rather
 * than a block of fill with letters on top.
 */
export function Hit({
  text,
  q,
}: {
  text: string;
  /**
   * One needle or several. The list search and a column's own filter box are
   * both live at once and both narrowed this row, so both are marked: a reader
   * who typed in two places should see both answers, not whichever the cell
   * happened to be told about.
   */
  q?: string | (string | undefined)[];
}) {
  const needles = (Array.isArray(q) ? q : [q])
    .map((n) => n?.trim().toLowerCase())
    .filter((n): n is string => Boolean(n));
  if (needles.length === 0) return <>{text}</>;

  /* EVERY RUN ANY NEEDLE HITS, merged. Two needles that overlap — "diesel" in
     the search box and "dies" in the column — would otherwise mark the same
     letters twice and split the word into fragments. */
  const hay = text.toLowerCase();
  const spans: [number, number][] = [];
  for (const n of needles) {
    let at = hay.indexOf(n);
    while (at !== -1) {
      spans.push([at, at + n.length]);
      at = hay.indexOf(n, at + 1);
    }
  }
  if (spans.length === 0) return <>{text}</>;
  spans.sort((a, b) => a[0] - b[0]);
  const merged: [number, number][] = [];
  for (const [from, to] of spans) {
    const last = merged[merged.length - 1];
    if (last && from <= last[1]) last[1] = Math.max(last[1], to);
    else merged.push([from, to]);
  }

  const parts: React.ReactNode[] = [];
  let at = 0;
  for (const [from, to] of merged) {
    if (from > at) parts.push(text.slice(at, from));
    parts.push(
      <mark
        key={`${from}-${to}`}
        className="rounded-xs bg-brand/25 font-medium text-foreground"
      >
        {text.slice(from, to)}
      </mark>
    );
    at = to;
  }
  if (at < text.length) parts.push(text.slice(at));
  return <>{parts}</>;
}

export function TwoLineCell({
  title,
  description,
  q,
}: {
  title: string;
  description: string;
  /** Filter text for this column — the matched run is marked. */
  q?: string | (string | undefined)[];
}) {
  return (
    <div className="flex min-w-0 flex-col">
      <span className="truncate text-sm text-foreground">
        <Hit text={title} q={q} />
      </span>
      <span className="truncate text-xs text-muted-foreground">
        <Hit text={description} q={q} />
      </span>
    </div>
  );
}

/**
 * First value plus a `+N` chip for the rest. The chip opens the shared
 * breakdown card ON CLICK (Pavan, 2026-10-14 — one way everywhere; was a
 * hover list). The count is the information here; the first value is only
 * an anchor. Rows may carry a sub-line and a figure (`rows`).
 */
export function OverflowList({
  values,
  label,
  rows,
}: {
  values: string[];
  label: string;
  /** Richer rows for the card — default: one per value. */
  rows?: BreakdownRow[];
}) {
  if (values.length === 0) {
    return <span className="text-sm text-muted-foreground">—</span>;
  }
  const [first, ...rest] = values;
  return (
    <div className="flex min-w-0 items-center gap-1.5">
      <span className="truncate text-sm text-foreground">{first}</span>
      {rest.length > 0 && (
        <OverflowChip
          count={rest.length}
          label={`Show all ${values.length} ${label}`}
          /* WIDER WHEN ROWS CARRY DETAIL — a sub-line and a figure. */
          width={rows ? 360 : undefined}
          card={{
            title: `All ${label} (${values.length})`,
            rows: rows ?? values.map((v) => ({ label: v })),
          }}
        />
      )}
    </div>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import { ChevronLeft, ChevronRight, CircleCheck, Info } from "lucide-react";

/**
 * THE PENDING STRIP — what a sheet's next act is still waiting on.
 *
 * SHARED, BECAUSE THE SECOND SHEET TO NEED IT IS THE PROMOTION SIGNAL. It was
 * written twice — once for the 3PL order and once for the service order — and
 * two copies of something this fiddly would have drifted in whichever half
 * gets opened less.
 *
 * It goes in `RecordSheet`'s `footerBanner`: the reason a primary is dead
 * belongs beside it, and beside it there is room for a clause, not for a list.
 * Each caller supplies its own items and its own section ids.
 */

export interface PendingItem {
  key: string;
  /** The INSTRUCTION — "Choose a customer", not "Customer". */
  label: string;
  /** The `id` of the section this item is about. Omitted = not pressable. */
  target?: string;
}

/**
 * SEND THE READER TO THE SECTION, and say which one it was.
 *
 * A strip that names a missing field and cannot take you to it is a label for
 * a hunt. The press scrolls the section into view and then blinks its outline
 * — because after a scroll the eye is on the MOVEMENT, not on the thing that
 * moved, and "it is this one" is a different statement from "here is some of
 * the form".
 *
 * ONCE, AND IT LEAVES NO TRACE (Pavan, 2026-09-22 — it was twice). Two flashes
 * is a thing asking to be watched; one is a thing pointing at itself and then
 * getting out of the way, and the reader is already looking because the scroll
 * took them there. Three times reads as an error, and a ring that stays is a
 * state — nothing about the record changed, so nothing about it should still
 * look different in a second.
 */
export function attend(id: string) {
  const el = document.getElementById(id);
  if (!el) return;

  /* SCROLL THE CONTAINER, NOT THE ELEMENT. `scrollIntoView` picks its own
     ancestor and hands the animation to the browser. Finding the scrollport
     and setting its offset is deterministic. */
  let port: HTMLElement | null = el.parentElement;
  while (port && port.scrollHeight <= port.clientHeight + 4) {
    port = port.parentElement;
  }
  if (!port) return;
  /* 12px of air above the section, so it does not sit flush against the header
     and read as clipped. */
  const top =
    port.scrollTop +
    el.getBoundingClientRect().top -
    port.getBoundingClientRect().top -
    12;

  /* ANIMATED BY HAND, because `behavior: "smooth"` does not survive in here.
     MEASURED in the running sheet: an instant scroll to 400 lands at 400; the
     same call with `smooth` lands at 0 — the sheet's scroll lock cancels the
     browser's animation the frame after it starts. The rAF loop is not
     decoration: without it the section either does not move or teleports, and
     the travel is what tells the reader this is the same sheet they were
     already in rather than a new screen. */
  const from = port.scrollTop;
  const distance = top - from;
  const started = performance.now();
  const DURATION = 320;
  const scroller = port;
  const step = (now: number) => {
    const t = Math.min((now - started) / DURATION, 1);
    /* ease-out cubic — fast away, slow into place, which is what makes an
       arrival read as an arrival. */
    scroller.scrollTop = from + distance * (1 - Math.pow(1 - t, 3));
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);

  /* NO FOCUS MOVE. Focusing the section, or a control inside it, was tried and
     dropped: inside a focus-trapped sheet the trap restores the scroll position
     of whatever it considers focused, which fights the travel. The blink is
     what says "this one", and focus stays on the strip — which is where the
     reader presses next if more than one item is outstanding.
     KEYBOARD GAP, KNOWN: a reader who presses this with the keyboard is shown
     the section but still has to Tab to it. */

  /* THE BLINK WAITS FOR THE SCROLL. Flashing a section that is still
     travelling spends the whole animation off screen. */
  window.setTimeout(() => blink(id), 320);
}

/** How long `blink` takes, start to finish — for anything sequencing after it. */
export const BLINK_MS = 800;

/**
 * THE FLASH ON ITS OWN, WITHOUT THE TRAVEL.
 *
 * FOR A SECOND, NARROWER "THIS ONE". After a section has been brought into
 * view and named, the thing actually worth reading inside it can be named
 * too — the Pricing unit, then the vendor's own column. Two statements, not
 * one longer one: "here" and then "this part of here". They must not overlap,
 * or the second reads as the first still going.
 */
export function blink(id: string) {
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.remove("fp-attention");
  /* Re-adding in the same frame does not restart a CSS animation; the reflow
     between the two is what does. */
  void el.offsetWidth;
  el.classList.add("fp-attention");
  window.setTimeout(() => el.classList.remove("fp-attention"), BLINK_MS);
}

/**
 * THE SAME FLASH, ACROSS SOMETHING THAT IS NOT ONE BOX.
 *
 * A column of a grid is a stack of separate cells: an outline round each of
 * them is a ladder, not a column. Every cell that belongs to the thing carries
 * `data-blink="<name>"`, and they flash a FILL together — which reads as the
 * one unit it is. (Pavan, 2026-09-22 — "blink should happen through this whole
 * unit".)
 */
export function blinkGroup(name: string) {
  const els = document.querySelectorAll<HTMLElement>(`[data-blink="${name}"]`);
  els.forEach((el) => {
    el.classList.remove("fp-attention-fill");
    /* Re-adding in the same frame does not restart a CSS animation; the reflow
       between the two is what does. */
    void el.offsetWidth;
    el.classList.add("fp-attention-fill");
    window.setTimeout(() => el.classList.remove("fp-attention-fill"), BLINK_MS);
  });
}

/**
 * One outstanding item at a time, with a counter and a way to step through
 * them, so three missing fields cost one line rather than three.
 *
 * THE WORD "PENDING" DOES NOT MOVE. It is the strip's subject and it is true
 * of every item under it; stepping swaps only the item. A label that changed
 * with the content would make the reader re-read what KIND of line this is on
 * every press.
 *
 * WHEN NOTHING IS OUTSTANDING IT SAYS SO, in the success channel, rather than
 * disappearing: an empty strip and a satisfied one are different states.
 */
export function PendingStrip({
  pending,
  /** What the strip says when the list is empty. */
  clearLabel = "Everything this record needs is filled in",
  tone = "neutral",
}: {
  pending: PendingItem[];
  clearLabel?: string;
  /**
   * `caution` once the strip is raised by pressing the primary with
   * something missing (2026-10-05) — it is the answer to a press and has to
   * be noticed. `neutral` (grey) where it simply stands on the sheet.
   */
  tone?: "neutral" | "caution";
}) {
  const [at, setAt] = React.useState(0);
  /* The list shortens as items are cleared, so the cursor has to be pulled
     back with it rather than pointing past the end. */
  const i = Math.min(at, Math.max(pending.length - 1, 0));
  React.useEffect(() => {
    if (at > pending.length - 1) setAt(Math.max(pending.length - 1, 0));
  }, [at, pending.length]);

  if (pending.length === 0) {
    return (
      <div className="flex items-center gap-2 text-sm text-fp-banner-accent-success">
        <CircleCheck className="size-4 shrink-0" />
        {clearLabel}
      </div>
    );
  }

  const step = pending[i];
  const chevron =
    "rounded-sm p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-30";

  return (
    /* IN THE STEP COLUMN (a narrow `@container`) the strip is two rows
       (Pavan, 2026-10-05): "Pending" on the left with the stepper on the
       right, and the item itself underneath, wrapping rather than truncating.
       No icon there. The first span dissolves (`contents`) so its pieces can
       be laid out against the counter. In the full-width footer band nothing
       changes. GREY, not caution orange (Pavan, 2026-10-05): what is left to
       do is information, not an alarm. */
    <div className="flex items-center justify-between gap-3 @max-[20rem]:flex-wrap @max-[20rem]:gap-y-1">
      <span
        className={cn(
          "flex min-w-0 items-center gap-2 text-sm @max-[20rem]:contents",
          tone === "caution" ? "text-fp-banner-accent-caution" : "text-muted-foreground"
        )}
      >
        <Info className="size-4 shrink-0 @max-[20rem]:hidden" />
        <span className="shrink-0 font-medium @max-[20rem]:order-1">Pending</span>
        {step.target ? (
          <button
            type="button"
            onClick={() => attend(step.target!)}
            className="min-w-0 truncate rounded-sm text-left @max-[20rem]:order-3 @max-[20rem]:basis-full @max-[20rem]:whitespace-normal underline decoration-current/40 underline-offset-4 outline-none transition-[text-decoration-color] hover:decoration-current focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            {step.label}
          </button>
        ) : (
          <span className="truncate @max-[20rem]:order-3 @max-[20rem]:basis-full @max-[20rem]:whitespace-normal">{step.label}</span>
        )}
      </span>
      <span className="flex shrink-0 items-center gap-0.5 text-xs tabular-nums text-muted-foreground @max-[20rem]:order-2">
        <button
          type="button"
          aria-label="Previous pending item"
          disabled={i === 0}
          onClick={() => setAt(i - 1)}
          className={chevron}
        >
          <ChevronLeft className="size-3.5" />
        </button>
        {i + 1} of {pending.length}
        <button
          type="button"
          aria-label="Next pending item"
          disabled={i >= pending.length - 1}
          onClick={() => setAt(i + 1)}
          className={chevron}
        >
          <ChevronRight className="size-3.5" />
        </button>
      </span>
    </div>
  );
}

import * as React from "react";
import { Check, Loader2, X } from "lucide-react";
import { StatusChip, type StatusTone } from "@/components/ui/status-chip";
import type { PillColor } from "@/components/ui/pill";
import { cn } from "@/lib/utils";
import { QuietPattern } from "@/components/ui/quiet-pattern";
import { Button } from "@/components/ui/button";
import { Sheet, SheetClose, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { SteppedFormBody } from "@/components/side-sheet/form-steps";
import { FormStepsContext } from "@/components/side-sheet/form-steps-context";
import { PendingStrip, attend, type PendingItem } from "./PendingStrip";

/**
 * Side-sheet shell for a single record — edit or create.
 *
 * Chrome is the DS's, taken from `side-sheet/SheetNarrow.tsx` (Figma "Side
 * Sheet" 27610:58293) and matched to the Fuel Orders order sheet so all three
 * sheets are identical where they should be:
 *   • SheetContent  w-560 (DS `narrow`), gap-0 p-0
 *   • header        border-b, p-4, items-start justify-between gap-4
 *   • body          p-4, flex-col gap-10   ← 40px between groups
 *   • footer        border-t, p-4, items-center justify-end gap-3
 *
 * The 40px group rhythm is the same deliberate override the order sheet
 * documents: these sheets carry far more fields than the DS reference, and at
 * the DS's gap-7 the groups stopped reading as groups. The 1:2 ratio against
 * SheetSection's gap-5 is preserved, so only the scale moved.
 *
 * CREATE AND EDIT ARE THE SAME SHEET. `mode="create"` swaps the title for the
 * create label and the submit button with it, and the caller seeds a blank
 * draft. One layout to learn, and no separate create form to drift.
 *
 * DS FOLLOW-UP: nothing here is screen-specific. This belongs beside
 * `side-sheet/` in the DS, with the order sheet moved onto it too.
 */
/**
 * A COLUMN'S COMFORTABLE WIDTH, by what it holds (Pavan, 2026-10-15). A
 * table-led sheet adds these up to find its width; one number per kind, so
 * the same column is the same width in every sheet.
 */
export const CELL = {
  /* TIGHTENED (Pavan, 2026-10-15): asset and product names are short, a
     quantity is at most six digits — the columns, and so the sheet, are only
     as wide as that. */
  /** A row's select checkbox, an expand chevron. */
  check: 44,
  /** "Top off" and other labelled checkboxes. */
  flag: 72,
  /** Top off — its label and the select-all, just before the quantity (DS ui §10i). */
  topOff: 104,
  /** A tank's level reading — gauge and % (portal, 2026-10-17). */
  level: 150,
  /** A tank monitor's battery. */
  battery: 100,
  /** The row's own thing — an asset, a product, a partner, a document. */
  name: 200,
  /** A pick from a short list — type, unit, condition, terminal. */
  pick: 160,
  /** A quantity or an amount, with its unit — six digits. */
  number: 110,
  date: 140,
  status: 140,
  /** Free text — a fault, a note. */
  text: 240,
  /** The row bin / a row menu. */
  bin: 52,
} as const;

export interface SheetFit {
  /** Each table's columns, as `CELL` widths; the widest table decides. */
  tables: number[][];
  /** The 340px right rail (summary · activity) beside the tables. */
  rail?: boolean;
}

/*
  THE PATTERN UNDER A SHORT FORM (Pavan, 2026-10-16). When what the sheet
  holds takes HALF the visible height or less, the DS quiet pattern fills
  the rest — to the body's left, right and bottom edges. Taller than that,
  there is no pattern and no space kept for it. Measured live, so a form
  that grows as it is filled loses the pattern when it passes half.
*/
const BODY_GAP = 40;
const BODY_PAD = 16;
function SheetPattern() {
  const ref = React.useRef<HTMLDivElement>(null);
  const [shown, setShown] = React.useState(false);
  React.useLayoutEffect(() => {
    const el = ref.current;
    const body = el?.parentElement;
    if (!el || !body) return;
    const measure = () => {
      const visible = body.clientHeight;
      if (!visible) return;
      const top = el.getBoundingClientRect().top - body.getBoundingClientRect().top + body.scrollTop;
      /* Where the content ends — the pattern's own gap taken out. */
      const content = top - BODY_PAD - (el.dataset.shown === "true" ? BODY_GAP : 0);
      setShown(content <= visible / 2);
    };
    const ro = new ResizeObserver(measure);
    ro.observe(body);
    for (const c of Array.from(body.children)) if (c !== el) ro.observe(c);
    const mo = new MutationObserver(() => {
      for (const c of Array.from(body.children)) if (c !== el) ro.observe(c);
      measure();
    });
    mo.observe(body, { childList: true });
    measure();
    return () => {
      ro.disconnect();
      mo.disconnect();
    };
  }, []);
  return (
    <div
      ref={ref}
      data-shown={shown}
      aria-hidden
      /* Hidden, it takes no room: zero height, and the gap above canceled. */
      className={cn(shown ? "-mx-4 -mb-4 flex min-h-24 flex-1" : "-mt-10 h-0 overflow-hidden")}
    >
      {shown && <QuietPattern className="flex-1" />}
    </div>
  );
}

/**
 * THE SHEET UNDERNEATH, for a sheet opened over it (Pavan, 2026-10-15). Now
 * that widths follow content, two sheets can be the same width, and the top
 * one would cover the other exactly — reading as the SAME sheet having
 * changed. A level-2 sheet is therefore never wider than the one beneath it
 * less the 56px gap, so a strip of it always shows.
 */
const ParentSheetWidth = React.createContext<number | null>(null);

/** BODY PADDING (16 + 16) AND THE TABLE BOX'S BORDERS. */
const FIT_PAD = 34;
const RAIL = 340 + 24;
export const FORM_WIDTH = 600;
export const DATA_WIDTH = 1200;
/** A data-intensive sheet's field grid — three across, at 1200. */
export const DATA_FIELDS = "grid grid-cols-3 gap-4";

/**
 * The width a table-led sheet takes. THE FORM SIDE IS NEVER NARROWER THAN A
 * 600 FORM'S (Pavan, 2026-10-15): beside a rail, small tables still leave the
 * fields two across at a readable width; the rail adds its own 364.
 */
export function fitWidth(fit: SheetFit): number {
  const widest = Math.max(0, ...fit.tables.map((t) => t.reduce((n, w) => n + w, 0)));
  return Math.max(FORM_WIDTH - FIT_PAD, widest) + FIT_PAD + (fit.rail ? RAIL : 0);
}

export interface RecordSheetProps {
  /**
   * THE WIDTH FOLLOWS WHAT IS IN THE SHEET (Pavan, 2026-10-15 — replaces the
   * fixed 560 / 864 / 1120 tiers and the 756 creation floor). A sheet sized
   * for more than it holds reads as empty.
   *
   *   `form`     600 — fields and text, no table. The default.
   *   `compact`  510 — CONTROLS rather than a form (a facet list).
   *   `data`     1200 at least — a DATA-INTENSIVE record's detail: many
   *              fields and several related-records tables (a 3PL customer,
   *              vendor, product, rental asset). Fields go three across
   *              (`DATA_FIELDS`); with `fit`, the wider of the two. Pavan,
   *              2026-10-15: "cramped … should have more width so that
   *              information can be easily consumed".
   *   `full`     the viewport less the gap — no form uses it now: every
   *              order sheet fits its tables (Pavan, 2026-10-15). Kept for a
   *              sheet showing its step column.
   *
   * A sheet that carries TABLES passes `fit` instead, and is as wide as its
   * widest table's columns at a comfortable width (`CELL`), plus the body's
   * padding, plus the 340px rail and its gap when it has one — never under
   * 600. Per step: a stepped sheet passes the tables of the step on show.
   *
   * THE GAP IS 56px AND IT IS THE ONE CONSTANT. Every width is clamped to
   * `100vw - 56px`, so no sheet reaches the edge or overflows a small screen.
   * A sheet opened OVER another one takes that gap TWICE — see `level`.
   */
  size?: "compact" | "form" | "data" | "full";
  /** Width from the sheet's tables — see `size` and `fitWidth`. */
  fit?: SheetFit;
  /**
   * HOW DEEP IN THE STACK THIS SHEET IS. `2` is a sheet opened OVER another
   * one — the invitation over an order, a partner's quote over an order.
   *
   * IT TAKES A SECOND GAP (Pavan, 2026-09-22). The 56px is what tells a reader
   * a sheet is over something; a second sheet at the same inset covers the
   * first exactly and reads as the SAME sheet having changed its contents.
   * 112px leaves a 56px strip of the sheet underneath showing, which says
   * "there is one of these behind this one" in the only language the stack
   * has.
   */
  level?: 1 | 2;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: "edit" | "create";
  /** Header title when editing, e.g. `Order #: 6104420`. */
  editTitle: string;
  /** Header title when creating, e.g. `Create Asset Order`. */
  createTitle: string;
  /** Submit label when editing. Defaults to the DS's `Save Changes`. */
  /**
   * THE EDIT-MODE PRIMARY. "Confirm", not "Save Changes" — autosave is the
   * default now, so by the time anybody looks at the footer the change is
   * already written and a Save would be claiming credit for work already
   * done. What is left to do is agree that the record is right.
   *
   * It is a per-sheet word: a footer that commits the record to a NEXT ACT
   * should say that act instead. Changed 2026-09-22.
   */
  editAction?: string;
  /** Submit label when creating — usually the same words as `createTitle`. */
  createAction: string;
  /** Rendered beside the title, e.g. a StatusChip. */
  headerAside?: React.ReactNode;
  /**
   * A second line under the title, inside the sticky header.
   *
   * For a fact about the record that must not scroll away — "this partner
   * holds the order" is the answer to a question the reader has while they are
   * looking at any part of the sheet, and at the bottom of a long step it was
   * only true where nobody was looking.
   */
  headerSubtitle?: React.ReactNode;
  /**
   * DRAFT AUTOSAVE, SAID OUT LOUD.
   *
   * A sheet that keeps a draft has to tell the reader it is keeping it, or
   * they behave as though it does not — they finish fields they meant to come
   * back to, and they hesitate to close. Three states and nothing else:
   * `saving` while a change settles, `saved` once it has, and `idle` before
   * anything has been typed, which shows nothing at all because there is
   * nothing to reassure anybody about yet.
   *
   * It sits by the TITLE, not the footer: it is a statement about the record,
   * not a control, and beside Save it would read as a second button. The
   * caller passes it through `DraftStatusChip`, which on a Draft swaps the
   * chip for the line "Draft saved" rather than showing both.
   */
  /**
   * The ··· at the right of the header, between the history icon and Close.
   * For acts ON the record that are not part of filling it in — deleting it.
   */
  headerMenu?: React.ReactNode;
  /**
   * Cancel in the footer. OFF on a sheet that autosaves its draft: "Cancel"
   * promises to undo, and a sheet that has already kept everything typed
   * cannot keep that promise. Close is the honest exit there.
   */
  showCancel?: boolean;
  /**
   * Controls at the far right of the header, left of Close.
   *
   * For things that OPEN something rather than change the record — a history,
   * a preview, a related list. They live in the header because they are not
   * part of the form and must not scroll away with it, and left of Close
   * because Close is the last thing on that edge in every sheet.
   */
  headerActions?: React.ReactNode;
  /**
   * A step strip under the header — `SheetSteps`. It sits above the body and
   * outside its scroll, because which step you are on is not something that
   * should be able to scroll away from you.
   */
  steps?: React.ReactNode;
  /** Disable submit while the draft is incomplete. */
  canSubmit?: boolean;
  /**
   * WHAT THE DEFAULT PRIMARY IS WAITING ON (Pavan, 2026-10-07 — G25). Given,
   * the default primary never goes dead: it stays pressable, and a press while
   * anything is listed (or `canSubmit` is false) raises the pending strip above
   * the footer and takes the reader to the first gap — the 3PL order / Quote
   * pattern. Ignored when `footerPrimary` replaces the button, and the caller's
   * own `footerBanner` wins over the strip.
   */
  pending?: PendingItem[];
  /**
   * Replaces the footer's primary button — and `null` removes it entirely.
   *
   * THE FOOTER'S RIGHT EDGE IS "THE MAIN THING TO DO HERE", and on a
   * multi-step sheet that is not the same act on every step. A step whose work
   * ends in a decision — accept this price — has a better claim to that slot
   * than a generic Save, and a step with nothing left to commit has no claim
   * at all. Omit the prop for the default Save/Create.
   */
  footerPrimary?: React.ReactNode;
  /**
   * Controls that ride in the footer, left of Cancel/Submit. For decisions
   * taken at the moment of committing rather than while filling the form —
   * they stay in view no matter how far the body has scrolled.
   */
  footerAside?: React.ReactNode;
  onSubmit: () => void;
  /**
   * A FIXED STRIP DIRECTLY ABOVE THE FOOTER, spanning the sheet.
   *
   * For what the footer's act is waiting on. The reason a primary is disabled
   * belongs beside it, and beside it there is room for a clause — not for a
   * list. This is where a sheet says what is still outstanding, in the one
   * place that does not scroll away from the button it is about.
   */
  footerBanner?: React.ReactNode;
  /** Classes for the banner while it sits under a stepped form's column. */
  footerBannerClassName?: string;
  /** A control on the step column's "Step N of M" row — form settings. */
  stepsAction?: React.ReactNode;
  /**
   * THE FORM AS STEPS (Pavan, 2026-10-05) — a column on the left listing the
   * form's steps, the form as one long scroll beside it, and the pending strip
   * at the foot of that column instead of above the footer. On by default for
   * every first-level sheet; the sheet takes the full width while the column
   * shows. The column only shows when there are two or more steps — see
   * `components/side-sheet/form-steps`.
   */
  stepNav?: boolean;
  /**
   * The step column itself. Off = the stepped form without the column on the
   * left (Pavan, 2026-10-06 — removed from the 3PL order sheets, archived in
   * docs/ds/ui/archive/step-column.md). OFF IN EVERY MODULE since 2026-10-07
   * (Pavan): pass `true` to bring it back on one sheet.
   */
  stepColumn?: boolean;
  children: React.ReactNode;
}

/**
 * Watch a draft and report whether it has been kept.
 *
 * ONE HOOK, SO EVERY DRAFT SHEET SAYS THE SAME THING. A sheet that autosaves
 * silently is a sheet people do not trust with unfinished work: they either
 * finish fields they meant to return to, or they hesitate to close. The
 * feedback is the feature.
 *
 * `saving` for 500ms after a change settles, then `saved`. It stays `idle`
 * until the FIRST change, because before anyone has typed there is nothing to
 * reassure them about — and a sheet that opens saying "Saved" is claiming to
 * have done something it has not.
 */
export function useDraftSaveState(draft: unknown, enabled = true) {
  const [state, setState] = React.useState<"idle" | "saving" | "saved">("idle");
  const serialised = React.useMemo(() => JSON.stringify(draft ?? null), [draft]);
  const first = React.useRef<string | null>(null);

  React.useEffect(() => {
    if (!enabled) {
      first.current = null;
      setState("idle");
      return undefined;
    }
    /* A SHEET FILLS ITS DRAFT ONE RENDER AFTER IT OPENS, so the first value
       seen here is `null` and the second is the untouched form. Treating that
       as an edit made every sheet open saying "Saved" — claiming to have kept
       something nobody had typed. The baseline is the first REAL draft. */
    if (draft === null || draft === undefined) return undefined;
    if (first.current === null) {
      first.current = serialised;
      return undefined;
    }
    if (serialised === first.current) return undefined;
    setState("saving");
    const t = window.setTimeout(() => setState("saved"), 500);
    return () => window.clearTimeout(t);
  }, [serialised, enabled, draft]);

  return state;
}

/**
 * The record's state in the header: what it IS, and whether the draft is kept.
 *
 * ONE THING WHEN THEY ARE THE SAME WORD. On a Draft, a status dot, the word
 * "Draft", a separator dot and the word "Saved" were four marks for one fact.
 * Once typing starts the chip gives way to plain text — "Draft saving…", then
 * "Draft saved" — which carries the status and the reassurance in one line.
 *
 * TWO WHEN THEY ARE NOT. An Assigned order being edited still has a status
 * worth seeing, and "Assigned saved" is not a sentence — so the status keeps
 * its chip and the save note sits beside it. The word stays "Draft" either
 * way, because what is kept is the draft of the edit, not the order.
 */
export function DraftStatusChip({
  tone,
  color,
  label,
  saveState = "idle",
  showStatus = true,
}: {
  tone: StatusTone;
  /* A STAGE COLOUR THE USER CHOSE (Pavan, 2026-10-09) — Sales stages keep
     the colour set in Sales Settings, in the header as in the table. */
  color?: PillColor | null;
  label: string;
  saveState?: "idle" | "saving" | "saved";
  /**
   * False drops the status chip and keeps only the save note — for a sheet
   * whose stage is already shown on its own track (Pavan, 2026-10-05).
   */
  showStatus?: boolean;
}) {
  const note =
    saveState === "saving" ? (
      <>
        <Loader2 className="size-3 animate-spin" />
        Draft saving…
      </>
    ) : (
      <>
        <Check className="size-3" />
        Draft saved
      </>
    );

  if (!showStatus) {
    if (saveState === "idle") return null;
    return (
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    );
  }

  if (saveState === "idle") {
    return (
      <StatusChip tone={tone} color={color} variant="soft">
        {label}
      </StatusChip>
    );
  }

  /* A DRAFT SAYS IT ONCE. "Draft saved" already contains the status, so the
     chip — its dot, its fill, its own word "Draft" — would be saying the same
     thing a second and third time. Plain text, one mark, one meaning. */
  if (label.toLowerCase() === "draft") {
    return (
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    );
  }

  /* NOT A DRAFT, so two things are true at once. An Assigned order still has a
     status worth seeing, and "Assigned saved" is not a sentence — the status
     keeps its chip and the save note sits beside it. The word stays "Draft"
     because what is kept is the draft of the edit, not the order. */
  return (
    <span className="flex items-center gap-2">
      <StatusChip tone={tone} color={color} variant="soft">
        {label}
      </StatusChip>
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    </span>
  );
}

export function RecordSheet({
  size = "form",
  fit,
  level = 1,
  open,
  onOpenChange,
  mode,
  editTitle,
  createTitle,
  editAction = "Confirm",
  createAction,
  headerAside,
  headerSubtitle,
  headerActions,
  headerMenu,
  showCancel = true,
  steps,
  canSubmit = true,
  pending,
  footerPrimary,
  footerAside,
  onSubmit,
  footerBanner,
  footerBannerClassName,
  stepsAction,
  stepNav,
  stepColumn = false,
  children,
}: RecordSheetProps) {
  const creating = mode === "create";
  const stepped = stepNav ?? level !== 2;
  const [navOn, setNavOn] = React.useState(false);
  const navShown = stepped && navOn;
  /* FULL WIDTH WHILE THE STEP COLUMN SHOWS (Pavan, 2026-10-05). */
  const fills = size === "full" || navShown;
  const parentWidth = React.useContext(ParentSheetWidth);
  const own =
    size === "data"
      ? Math.max(DATA_WIDTH, fit ? fitWidth(fit) : 0)
      : fit
        ? fitWidth(fit)
        : size === "compact"
          ? 510
          : FORM_WIDTH;
  const width = level === 2 && parentWidth !== null ? Math.min(own, parentWidth - 56) : own;
  /* WHY (Pavan, 2026-10-07). A dead primary says why on press (G25): the
     strip is raised by the press, not shown up front, and drops on close. */
  const [pendingRaised, setPendingRaised] = React.useState(false);
  React.useEffect(() => {
    if (!open) setPendingRaised(false);
  }, [open]);
  const saysWhy = pending !== undefined;
  const notReady = !canSubmit || (pending?.length ?? 0) > 0;
  const banner =
    footerBanner ??
    (saysWhy && pendingRaised ? <PendingStrip tone="caution" pending={pending} /> : undefined);
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        showCloseButton={false}
        /* THE GAP IS A VARIABLE, so one set of classes serves both levels. A
           second-level sheet takes 112 — the constant, twice — and the strip
           of the sheet beneath it is what says it is second. */
        style={
          {
            "--fp-sheet-gap": level === 2 ? "112px" : "56px",
            /* SCALED IN THE WCAG MODES — wider text, wider sheet (§10n). */
            "--fp-sheet-w": `calc(${width}px * var(--fp-scale, 1))`,
          } as React.CSSProperties
        }
        className={cn(
          "gap-0 p-0",
          fills
            ? /* FULL — the intense forms, and any sheet showing its step column. */
              "w-[calc(var(--fp-vw)-var(--fp-sheet-gap))] sm:max-w-[calc(var(--fp-vw)-var(--fp-sheet-gap))]"
            : /* THE CONTENT'S WIDTH, clamped by the gap (`--fp-sheet-w`). */
              "w-[min(var(--fp-sheet-w),calc(var(--fp-vw)-var(--fp-sheet-gap)))] sm:max-w-[min(var(--fp-sheet-w),calc(var(--fp-vw)-var(--fp-sheet-gap)))]"
        )}
      >
        <div className="flex items-start justify-between gap-4 border-b border-border p-4">
          <div className="flex min-w-0 flex-col gap-1">
            <div className="flex items-center gap-2.5">
              <SheetTitle className="text-base">
                {creating ? createTitle : editTitle}
              </SheetTitle>
              {headerAside}
            </div>
            {headerSubtitle}
          </div>
          <div className="flex shrink-0 items-center gap-1">
            {headerActions}
            {headerMenu}
            <SheetClose className="rounded-sm p-1 text-muted-foreground opacity-70 outline-none transition-opacity hover:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50">
              <X className="size-4" />
              <span className="sr-only">Close</span>
            </SheetClose>
          </div>
        </div>

        {/* ACROSS THE SHEET only without a step column; with one, the band
            starts where the form starts (Pavan, 2026-10-05). */}
        {steps && !navShown && (
          /* NO RULE UNDER THE STEPS (Pavan, 2026-10-16) — the strip keeps the
             sheet's own white, and the form scrolls under it. */
          <div className="shrink-0 bg-popover px-4">{steps}</div>
        )}

        {stepped ? (
          <SteppedFormBody
            footer={navShown ? banner : undefined}
            footerClassName={footerBannerClassName}
            top={navShown ? steps : undefined}
            onShownChange={setNavOn}
            stepsAction={stepsAction}
            hideColumn={!stepColumn}
          >
            <ParentSheetWidth.Provider value={fills ? 99999 : width}>{children}</ParentSheetWidth.Provider>
            <SheetPattern />
          </SteppedFormBody>
        ) : (
          <FormStepsContext.Provider value={false}>
            <div className="flex min-h-0 flex-1 flex-col gap-10 overflow-auto p-4">
              <ParentSheetWidth.Provider value={fills ? 99999 : width}>{children}</ParentSheetWidth.Provider>
            <SheetPattern />
            </div>
          </FormStepsContext.Provider>
        )}

        {banner && !navShown && (
          /* ABOVE THE FOOTER AND OUTSIDE THE SCROLL — the same reason the
             stage bar sits under the header: a strip that describes the
             footer's button has to be visible whenever the button is. */
          <div className="shrink-0 border-t border-border px-4 py-2.5">
            {banner}
          </div>
        )}

        <div className="flex shrink-0 flex-wrap items-center justify-between gap-3 border-t border-border p-4">
          <div className="flex flex-wrap items-center gap-x-8 gap-y-2">
            {footerAside}
          </div>
          <div className="flex items-center gap-3">
          {showCancel && (
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
          )}
          {/* `undefined` = the default Save/Create; anything else replaces it,
              and `null` leaves the slot empty on a step with nothing to
              commit. */}
          {footerPrimary !== undefined ? (
            footerPrimary
          ) : (
            /* WHY (Pavan, 2026-10-07). With `pending` the button is never
               disabled — a press while not ready names the gap (G25). Without
               it, the old `disabled` stays so no caller changes unasked. */
            <Button
              disabled={!saysWhy && !canSubmit}
              onClick={() => {
                if (saysWhy && notReady) {
                  setPendingRaised(true);
                  const first = pending?.find((p) => p.target);
                  if (first?.target) attend(first.target);
                  return;
                }
                onSubmit();
                onOpenChange(false);
              }}
            >
              {creating ? createAction : editAction}
            </Button>
          )}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { SheetSection, SheetSectionRemove } from "@/components/side-sheet/parts";
import { RuleFrequencyPicker, blankFrequency, type RuleFrequency } from "./threepl/RuleFrequency";

/*
  RECURRING ORDER, AS THE 3PL LOAD ORDER (Pavan, 2026-10-20) — an optional
  section on every order sheet that can repeat: a dashed "Add" row until it's
  asked for, then the recurring rule's own frequency unit in a box, removed
  with the section's minus. One unit for every module, so a repeat is set the
  same way wherever it's set.
*/
export function RecurringOrderSection({
  on,
  schedule,
  plannedDay,
  onChange,
  onRemove,
  locked,
  title = "Recurring order",
  id,
}: {
  on: boolean;
  schedule?: RuleFrequency | null;
  /** The planned date's weekday — a new repeat starts on it, weekly. */
  plannedDay?: number;
  /** Turned on, or changed — the unit as it now stands. */
  onChange: (f: RuleFrequency) => void;
  onRemove: () => void;
  locked?: boolean;
  title?: string;
  id?: string;
}) {
  if (locked && !on) return null;
  return (
    <SheetSection
      id={id}
      title={title}
      action={on && !locked ? <SheetSectionRemove label={`Remove ${title.toLowerCase()}`} onClick={onRemove} /> : undefined}
    >
      {!on ? (
        <div className="flex items-center justify-between gap-4 rounded-md border border-dashed border-fp-outline-1 px-4 py-3">
          <span className="text-sm text-foreground">Add Recurring Order</span>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onChange(schedule ?? { ...blankFrequency(), days: [plannedDay ?? new Date().getDay()] })}
          >
            <Plus /> Add
          </Button>
        </div>
      ) : (
        <fieldset disabled={locked} className="min-w-0 rounded-md border border-fp-outline-1 p-4">
          <RuleFrequencyPicker value={schedule ?? blankFrequency()} onChange={onChange} />
        </fieldset>
      )}
    </SheetSection>
  );
}

import * as React from "react";
import {
  Ban,
  DollarSign,
  History as HistoryIcon,
  Layers,
  Mail,
  Pencil,
  Plus,
  Truck,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";

/*
  THE RECORD SHEET'S TWO SHARED CARDS (Pavan, 2026-10-07 — ux §Record sheets).
  Lifted out of the 3PL order sheet unchanged, so every module's sheet shows
  what its form computes in the SUMMARY CARD and its history in the ACTIVITY
  CARD, instead of each drawing its own. The 3PL sheet imports these back; a
  change here is a change there.
*/

/** The trail's clock: the day and the minute, which is the grain anyone asks
 *  a history in. Seconds would be precision nobody uses. */
const AUDIT_FMT = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  hour: "numeric",
  minute: "2-digit",
});

/**
 * WHAT AN ACTIVITY ENTRY IS ABOUT, from what it says.
 *
 * The audit trail is one line of prose per change, which is the right thing to
 * store and the wrong thing to scan: six lines of identical grey text hide the
 * one that matters. A mark gives each entry a kind at a glance — money, a
 * message that left the building, something added, something that moved
 * backwards — and money and creation get a tint, because those are the two the
 * eye should catch on the way past.
 */
function auditMark(text: string): { icon: React.ReactNode; tone: string } {
  const t = text.toLowerCase();
  if (/\bquote|price|\$|margin|rate/.test(t))
    return {
      icon: <DollarSign />,
      tone: "border-status-success/30 bg-status-success/10 text-status-success",
    };
  if (/invit|sent|notif|email|acknowled/.test(t))
    return {
      icon: <Mail />,
      tone: "border-fp-banner-accent-info/30 bg-fp-banner-accent-info/10 text-fp-banner-accent-info",
    };
  if (/created/.test(t))
    return {
      icon: <Plus />,
      tone: "border-status-success/30 bg-status-success/10 text-status-success",
    };
  if (/cancel|remov|delet|block/.test(t))
    return {
      icon: <Ban />,
      tone: "border-status-failed/30 bg-status-failed/10 text-status-failed",
    };
  if (/load order|terminal|supplier/.test(t))
    return { icon: <Layers />, tone: "border-border bg-card text-muted-foreground" };
  if (/asset|product|gal/.test(t))
    return { icon: <Truck />, tone: "border-border bg-card text-muted-foreground" };
  return { icon: <Pencil />, tone: "border-border bg-card text-muted-foreground" };
}

/**
 * A label/value row in a rail card, and — where there is one — the ARITHMETIC
 * BEHIND THE FIGURE, on hover.
 *
 * A total in a summary is a claim, and the reader's next question is always
 * the same: made of what? Without it the answer is a table two sections away,
 * and comparing the two means holding one number in your head while you scroll
 * to the other. A tooltip puts the working where the claim is. It is NOT a
 * substitute for the tables — those are where the figures are TYPED — it is
 * the read-only account of how they add up.
 */
export function RailRow({
  label,
  value,
  breakdown,
  variant = "rail",
}: {
  label: React.ReactNode;
  value: React.ReactNode;
  /** One line per contribution. Rendered only when there is something to show. */
  breakdown?: { label: string; value: string }[];
  /** `line` / `total` — the Summary card's statement rows (2026-10-05). */
  variant?: "rail" | "line" | "total";
}) {
  const row = (
    <div
      className={cn(
        "flex items-baseline justify-between gap-3",
        variant === "rail" ? "px-4 py-2.5" : "py-1",
        /* A TOTAL NEVER CUTS ITS LABEL (Pavan, 2026-10-20) — too long for
           one line, the figure drops under it, right-aligned. */
        variant === "total" && "flex-wrap gap-y-0.5",
        breakdown?.length && "cursor-help"
      )}
    >
      <dt
        className={cn(
          "min-w-0 truncate",
          variant === "rail" && "shrink-0 text-xs text-muted-foreground",
          variant === "line" && "text-sm text-foreground",
          variant === "total" && "shrink-0 overflow-visible text-base font-medium text-foreground"
        )}
      >
        {label}
      </dt>
      <dd
        className={cn(
          "min-w-0 shrink-0 truncate tabular-nums",
          variant === "rail" && "text-sm text-foreground",
          variant === "line" && "text-sm text-muted-foreground",
          variant === "total" && "ml-auto text-base font-semibold text-foreground",
          /* THE DOTTED RULE IS THE WHOLE AFFORDANCE. A figure that explains
             itself has to say so without a second control beside it. */
          breakdown?.length &&
            "underline decoration-dotted decoration-muted-foreground underline-offset-4"
        )}
      >
        {value}
      </dd>
    </div>
  );
  if (!breakdown?.length) return row;
  return (
    <Tooltip>
      <TooltipTrigger asChild>{row}</TooltipTrigger>
      <TooltipContent side="left" className="max-w-xs">
        <span className="flex flex-col gap-1">
          {breakdown.map((b) => (
            <span key={b.label} className="flex items-baseline justify-between gap-4">
              <span className="min-w-0 truncate">{b.label}</span>
              <span className="shrink-0 tabular-nums">{b.value}</span>
            </span>
          ))}
        </span>
      </TooltipContent>
    </Tooltip>
  );
}

