  "Foothill", "Central Coast", "Ironwood", "Blue Mesa", "Cascade", "Rimrock",
  "Saguaro", "High Desert", "Copper Ridge", "Frontier", "Trailhead", "Stonegate",
  "Windward", "Silverline", "Cornerstone", "Basin", "Overland", "Ridgeline",
  "Northstar", "Sunfield", "Talon", "Junction", "Cypress", "Beacon",
] as const;

const VENDOR_TAILS = [
  "Carriers", "Bulk Transport", "Fuel Logistics", "Hauling", "Tank Movers",
  "Petro", "Fuel Service", "Energy", "Transport", "Distribution", "Tanklines",
  "Freight", "Petroleum", "Fuels", "Dispatch",
] as const;

const VENDOR_INSTRUCTIONS = [
  "Send the BOL within 2 hours of delivery or the invoice is held.",
  "Dispatch answers the shared line, not the mobile, before 6am.",
  "Confirm every load by email — they do not use the portal.",
  "Ask for the same driver on the university sites; he is badged.",
  "Quote includes the fuel surcharge. Do not add it twice.",
] as const;

function makeVendor(spec: VendorSeed & { seed: number; id: string; index: number }): Vendor {
  const r = rng(spec.seed);
  const [city, st] = spec.base.split(", ");
  const place = PLACES.find((p) => p.city === city) ?? pickFrom(r, PLACES);
  const domain = domainFor(spec.name);
  const dispatchName = personName(r);
  const mainName = personName(r);
  const accountingName = personName(r);

  const daysToCompliance = Math.round(
    (new Date(`${spec.complianceValidTo}T00:00:00Z`).getTime() - TODAY.getTime()) / 86_400_000
  );
  /* COMPLIANCE STATUS IS DERIVED, never stored independently. A vendor whose
     certificate expired last month and whose status still says Valid is the
     exact failure this directory exists to prevent. */
  const complianceStatus: ComplianceStatus =
    daysToCompliance < 0 ? "Expired" : daysToCompliance < 60 ? "Expiring" : "Valid";

  const tiers: RateCardLine[] = [
    { id: `${spec.id}-rc-1`, label: "Base haul", rate: Number((0.18 + r() * 0.22).toFixed(3)), unit: "per gal", minGallons: null, fuelSurcharge: Number((0.02 + r() * 0.05).toFixed(3)) },
    { id: `${spec.id}-rc-2`, label: "Volume 2,500 gal+", rate: Number((0.12 + r() * 0.14).toFixed(3)), unit: "per gal", minGallons: 2500, fuelSurcharge: Number((0.02 + r() * 0.04).toFixed(3)) },
  ];
  if (spec.businessLines.includes("Asset Movement")) {
    tiers.push({ id: `${spec.id}-rc-3`, label: "Asset move", rate: intBetween(r, 180, 480), unit: "flat", minGallons: null, fuelSurcharge: null });
  }
  if (spec.businessLines.includes("Emergency Response")) {
    tiers.push({ id: `${spec.id}-rc-4`, label: "After-hours callout", rate: intBetween(r, 110, 260), unit: "per hour", minGallons: null, fuelSurcharge: null });
  }

  const contactRows: DirectoryContact[] = [
    { id: `${spec.id}-ct-1`, name: dispatchName, role: "Dispatch", phone: phoneNumber(r), email: emailFor(dispatchName, domain), isPrimary: true, notes: maybe(r, 0.25, "Best reached on the dispatch line before 5am.") },
    { id: `${spec.id}-ct-2`, name: mainName, role: "Account Manager", phone: maybe(r, 0.8, phoneNumber(r)), email: maybe(r, 0.85, emailFor(mainName, domain)), isPrimary: false, notes: null },
    { id: `${spec.id}-ct-3`, name: accountingName, role: "Accounts Receivable", phone: maybe(r, 0.5, phoneNumber(r)), email: maybe(r, 0.9, `ar@${domain}`), isPrimary: false, notes: null },
  ].slice(0, intBetween(r, 1, 3));

  const createdAt = new Date(shiftDays(TODAY, -intBetween(r, 120, 1700)).setUTCHours(11)).toISOString();
  const updatedAt = new Date(shiftDays(TODAY, -intBetween(r, 0, 70)).setUTCHours(16)).toISOString();

  const v: Vendor = {
    id: spec.id,
    name: spec.name,
    erpVendorId: maybe(r, 0.8, `VEND-${3000 + spec.index}`),
    legalBusinessName: maybe(r, 0.7, `${spec.name} LLC`),
    dbaName: maybe(r, 0.25, spec.name.split(" ")[0]),
    taxId: maybe(r, 0.6, `${intBetween(r, 10, 99)}-${intBetween(r, 1000000, 9999999)}`),
    status: spec.active ? "active" : "inactive",
    vendorType: pickFrom(r, VENDOR_TYPES),

    mainContactName: mainName,
    dispatchContactName: dispatchName,
    accountingContactName: maybe(r, 0.7, accountingName),
    escalationContactName: maybe(r, 0.4, personName(r)),
    phone: phoneNumber(r),
    dispatchPhone: phoneNumber(r),
    email: maybe(r, 0.85, `info@${domain}`),
    dispatchEmail: `dispatch@${domain}`,
    accountingEmail: maybe(r, 0.75, `ap@${domain}`),
    contacts: contactRows,

    addressLine1: streetAddress(r),
    addressLine2: maybe(r, 0.15, `Dock ${intBetween(r, 1, 24)}`),
    city,
    state: st,
    zip: place.zip,
    country: "USA",
    base: spec.base,

    serviceAreaType: pickFrom(r, SERVICE_AREA_TYPES),
    serviceStates: spec.serviceStates,
    coveredCities: someOf(r, PLACES.filter((p) => spec.serviceStates.includes(STATE_NAMES[p.state] ?? "")).map((p) => p.city), 5),
    coveredZips: r() < 0.3 ? someOf(r, PLACES.map((p) => p.zip), 4) : [],
    maxRadiusMiles: maybe(r, 0.5, intBetween(r, 3, 30) * 25),

    businessLines: spec.businessLines,
    supportedProductIds: [],
    supportedOrderTypes: someOf(r, ["Delivery", "Core", "Emergency", "Transport", "Asset Movement", "Pump Out"] as const, 4),
    topOffCapable: r() < 0.62,
    assetHandlingCapable: spec.businessLines.includes("Asset Movement") || r() < 0.2,
    afterHoursCapable: spec.businessLines.includes("Emergency Response") || r() < 0.35,

    complianceStatus,
    complianceValidTo: spec.complianceValidTo,
    insuranceExpiry: maybe(r, 0.9, spec.complianceValidTo),
    licenseNumbers: someOf(r, [`MC-${intBetween(r, 100000, 999999)}`, `DOT-${intBetween(r, 1000000, 3999999)}`, `HM-${intBetween(r, 10000, 99999)}`], 2),
    documents: seedAttachments(r, [
      "Certificate of Insurance.pdf", "W-9.pdf", "Operating Authority.pdf",
      "Hazmat Endorsement.pdf", "Signed Carrier Agreement.pdf", "Safety Rating Letter.pdf",
    ], 4),
    approvedForAssignment: spec.active && r() < 0.88,
    active: spec.active,

    defaultRateCardId: tiers[0]?.id ?? null,
    rateCard: tiers,
    minimumCharge: maybe(r, 0.65, intBetween(r, 3, 20) * 25),
    paymentTerms: pickFrom(r, ["Net 15", "Net 30", "Net 45", "Quick pay 2/10"] as const),
    accountingVendorId: maybe(r, 0.7, `NS-V-${intBetween(r, 1000, 9999)}`),

    availabilityStatus: spec.active
      ? pickFrom(r, ["Available", "Available", "Available", "Limited", "Unavailable"] as const)
      : "Unavailable",
    /* Blackouts are the reason an eligible vendor is still not offered on a
       given date, so a slice of the list has to actually have some. */
    blackoutDates: r() < 0.28
      ? Array.from({ length: intBetween(r, 1, 4) }, () => dateOffset(intBetween(r, -10, 120)))
      : [],
    assignmentPriority: intBetween(r, 1, 5),
    preferredCustomerIds: [],

    safetyScore: spec.safetyScore,
    distanceMi: spec.distanceMi,
    emailsEnabled: spec.emailsEnabled,
    hasAccount: spec.hasAccount,
    vendorInstruction: maybe(r, 0.45, pickFrom(r, VENDOR_INSTRUCTIONS)),

    tags: r() < 0.65 ? someOf(r, VENDOR_TAGS, 3) : [],
    notes: maybe(r, 0.3, "Reliable on short notice. Rates reviewed each January."),
    attachments: seedAttachments(r, ["Rate Card 2026.xlsx", "Coverage Map.png", "Meeting Notes.pdf"], 2),
    audit: [],
    createdAt,
    updatedAt,
  };

  v.audit = seedAudit(r, {
    createdAt,
    updatedAt,
    noun: "Vendor",
    fields: [
      "Compliance status", "Insurance expiry", "Rate card", "Service states",
      "Dispatch email", "Assignment approval", "Availability", "Business lines",
    ],
  });
  return v;
}

function buildVendors(): Vendor[] {
  const out: Vendor[] = CORE_VENDORS.map((v, i) =>
    makeVendor({ ...v, seed: 11_000 + i, id: `vd-${i + 1}`, index: i })
  );

  let i = 0;
  while (out.length < 80) {
    const r = rng(12_000 + i);
    const name = `${pickFrom(r, VENDOR_HEADS)} ${pickFrom(r, VENDOR_TAILS)}`;
    if (!out.some((v) => v.name === name)) {
      const place = pickFrom(r, PLACES);
      const states = someOf(
        r,
        Object.values(STATE_NAMES),
        3
      );
      /* The vendor's own state is always covered — a carrier that does not
         serve the state it is based in is a data bug, not a business case. */
      const home = STATE_NAMES[place.state];
      if (home && !states.includes(home)) states.unshift(home);

      out.push(
        makeVendor({
          seed: 12_000 + i,
          id: `vd-${out.length + 1}`,
          index: out.length,
          name,
          base: `${place.city}, ${place.state}`,
          businessLines: someOf(r, BUSINESS_LINES, 3),
          safetyScore: intBetween(r, 58, 99),
          distanceMi: intBetween(r, 4, 180),
          emailsEnabled: r() < 0.85,
          hasAccount: r() < 0.6,
          active: r() < 0.88,
          serviceStates: states,
          /* A quarter of the list is out of date on purpose: "has overdue
             docs" is a filter, and a filter with no matches is untestable. */
          complianceValidTo: dateOffset(r() < 0.25 ? -intBetween(r, 5, 400) : intBetween(r, 20, 900)),
        })
      );
    }
    i += 1;
    if (i > 600) break;
  }
  return out;
}

export const VENDORS: Vendor[] = buildVendors();

export const vendorById = (id: string | null) =>
  id ? (VENDORS.find((v) => v.id === id) ?? null) : null;

export const vendorName = (id: string | null) => vendorById(id)?.name ?? "—";

/** The other direction, for a control whose value is the name on screen. */
export const vendorByName = (name: string) =>
  VENDORS.find((v) => v.name === name);

/**
 * WHY A VENDOR CANNOT TAKE THIS ORDER — the reason, or null when it can.
 *
 * A REASON, NOT A BOOLEAN. "Not offered" is the answer people escalate;
 * "compliance expired 30 Jun 2026" is the answer they act on, and it is the
 * same sentence whether it is read by the person picking or by the person they
 * ring afterwards. The rules are checked in the order they can be fixed in:
 * a deactivated vendor is somebody's decision, an expired document is a task,
 * geography and capability are facts about the vendor, and a blackout is a
 * fact about the DAY rather than about the vendor at all.
 */
export function vendorBlockedReason(
  v: Vendor,
  order: { businessLine: BusinessLine; state: string; on: Date }
): string | null {
  if (!v.active) return "Deactivated";
  if (!v.approvedForAssignment) return "Not approved for assignment";
  const [y, m, d] = v.complianceValidTo.split("-").map(Number);
  if (new Date(y, m - 1, d) < order.on) {
    return `Compliance expired ${v.complianceValidTo}`;
  }
  if (!v.businessLines.some((b) => b === order.businessLine)) {
    return `Does not run ${order.businessLine}`;
  }
  if (!v.serviceStates.includes(order.state)) {
    return `Does not serve ${order.state}`;
  }
  if (v.availabilityStatus === "Unavailable") return "Marked unavailable";
  const iso = order.on.toISOString().slice(0, 10);
  if (v.blackoutDates.includes(iso)) return `Blacked out on ${iso}`;
  return null;
}

/** Docs that have lapsed, or lapse inside 60 days — the "overdue docs" filter. */
export const hasOverdueDocs = (v: Vendor): boolean =>
  v.complianceStatus === "Expired" || v.complianceStatus === "Expiring";

/* ────────────────────────────────────────────────────────────── list view ──
   NOTHING HERE SUMS. A vendor has a safety score and a distance, and both are
   properties of one vendor rather than quantities that add up — an average
   safety score across a group would be a different statistic wearing the same
   place as a total, and a summed distance is meaningless. So the list passes no
   `measureOf`, and its group headers carry a count alone. */

export type VendorColumnKey =
  | "name"
  | "dispatch"
  | "lines"
  | "erpId"
  | "address"
  | "serviceArea"
  | "products"
  | "status"
  | "rateCard"
  | "assigned"
  | "instruction"
  | "actions";

export interface VendorColumnDef {
  key: VendorColumnKey;
  label: string;
  width: number;
  sortable?: boolean;
  align?: "right" | "center";
}

/*
  TWELVE COLUMNS, DOWN FROM TWENTY — and the cut is by a rule, not by taste.

  A VENDOR LIST EXISTS TO ANSWER ONE QUESTION: who can take this work. So a
  column earns its place if it feeds that answer. The eligibility inputs are
  active status, compliance, business lines, service area, supported products —
  those stay. Everything else was reference, and reference belongs in the
  record, which is one click away and has room for it.

  WHAT LEFT THE TABLE, and why:
    · Safety Score, Distance  — ranking inputs at ASSIGNMENT time, not
      directory-browsing facts. Distance especially: it is miles from a
      SHIP-TO, and a directory has no ship-to, so the number here is a
      placeholder pretending to be a measurement. Both remain FILTERS — a
      facet does not need a column to work.
    · Emails on/off, Vendor App  — per-vendor comms config. Real, rarely
      looked at, and never the reason somebody opens this list.
    · City, State  — folded into Address, as on Customers.
    · Compliance  — folded under the vendor's name, where the name is.
    · Dispatch Phone + Email  — one column, two lines.
*/
/*
  THE ORDER IS THE ONE THE READER ARRANGED, adopted as the default rather than
  argued with. Identity first, then the number that says how busy they are,
  then how to reach them, then what they can do, then where, then the
  commercial terms.

  Load is third on purpose. Once a shortlist is eligible, "how much work are
  they already carrying" is the next question, and it was ninth.
*/
export const VENDOR_COLUMNS: VendorColumnDef[] = [
  { key: "name", label: "Vendor Name", width: 220, sortable: true },
  { key: "erpId", label: "Vendor ID", width: 110, sortable: true },
  /* CENTRED, not right-aligned. These are 1-2 digit counts that get READ, not
     compared down the column — at 150px a right edge sits so far from a
     15px header that it reads as a mistake. `tabular-nums` stays, so the
     digits still line up with each other. Money and long figures keep
     `right`, where lining up the units is the whole point. */
  { key: "assigned", label: "Assigned Orders", width: 140, sortable: true },
  { key: "dispatch", label: "Dispatch", width: 250, sortable: true },
  { key: "lines", label: "Business Lines", width: 210, sortable: true },
  { key: "address", label: "Address", width: 160, sortable: true },
  { key: "serviceArea", label: "Service Area", width: 150, sortable: true },
  { key: "products", label: "Supported Products", width: 270, sortable: true },
  { key: "status", label: "Status", width: 100, sortable: true },
  { key: "rateCard", label: "Default Rate Card", width: 150, sortable: true },
  { key: "instruction", label: "Notes", width: 80, sortable: true },
  { key: "actions", label: "", width: 44 },
];

export const VENDOR_SEARCH_FIELDS = [
  { key: "name", label: "Vendor", text: (v: Vendor) => `${v.name} ${v.legalBusinessName ?? ""}` },
  { key: "contact", label: "Contact", text: (v: Vendor) => `${v.dispatchContactName ?? ""} ${v.mainContactName ?? ""} ${v.dispatchEmail ?? ""} ${v.dispatchPhone ?? ""}` },
  { key: "city", label: "City", text: (v: Vendor) => v.city ?? "" },
  { key: "state", label: "State", text: (v: Vendor) => `${v.state ?? ""} ${v.serviceStates.join(" ")}` },
  { key: "lines", label: "Business Lines", text: (v: Vendor) => v.businessLines.join(" ") },
];

/** Free-text across everything a vendor is findable by. */
export function matchesVendor(v: Vendor, q: string): boolean {
  return `${v.name} ${v.base} ${v.businessLines.join(" ")} ${v.dispatchContactName ?? ""} ${v.dispatchEmail ?? ""} ${v.serviceStates.join(" ")} ${v.erpVendorId ?? ""}`
    .toLowerCase()
    .includes(q);
}

export function matchesVendorIn(v: Vendor, q: string, scope: string): boolean {
  const f = VENDOR_SEARCH_FIELDS.find((x) => x.key === scope);
  return f ? f.text(v).toLowerCase().includes(q) : true;
}

export interface VendorSortState {
  key: VendorColumnKey;
  dir: "asc" | "desc";
}

export function sortVendors(rows: Vendor[], sort: VendorSortState | null): Vendor[] {
  if (!sort) return rows;
  const dir = sort.dir === "asc" ? 1 : -1;
  const of = (v: Vendor): string | number => {
    switch (sort.key) {
      case "name": return v.name;
      case "erpId": return v.erpVendorId ?? "";
      /* Sorting by address means sorting by PLACE, not by house number — the
         same call the Customers list makes on its merged column. */
      case "address": return `${v.city ?? ""} ${v.state ?? ""}`.trim();
      case "status": return v.active ? 1 : 0;
      case "assigned": return assignedOrderCount(v.id);
      /* EVERY COLUMN SORTS (Pavan, 2026-10-07) — by what the cell prints
         first; an icon column sorts the rows with a note first. */
      case "dispatch": return v.dispatchPhone ?? "";
      case "lines": return v.businessLines[0] ?? "";
      case "serviceArea": return v.serviceStates[0] ?? "";
      case "products": return v.supportedProductIds.length;
      case "rateCard":
        return (v.rateCard.find((l) => l.id === v.defaultRateCardId) ?? v.rateCard[0])?.label ?? "";
      case "instruction": return v.vendorInstruction ? 0 : 1;
      default: return v.name;
    }
  };
  return [...rows].sort((a, b) => {
    const x = of(a);
    const y = of(b);
    if (typeof x === "number" && typeof y === "number") return (x - y) * dir;
    return String(x).localeCompare(String(y)) * dir;
  });
}

/**
 * How many live orders this vendor is carrying.
 *
 * Injected rather than imported: `orders.ts` already imports from here for the
 * picker, and reaching back the other way would close a cycle. The Directory
 * screen sets it once on mount from the order list it can see.
 */
let assignedCounts: Record<string, number> = {};
export const setAssignedOrderCounts = (counts: Record<string, number>) => {
  assignedCounts = counts;
};
export const assignedOrderCount = (vendorId: string): number => assignedCounts[vendorId] ?? 0;

/** The state used by the safety filter — a RANGE, per §5.5. */
export const SAFETY_BANDS = ["90–100", "80–89", "70–79", "Below 70"] as const;

export function safetyBand(score: number): string {
  if (score >= 90) return "90–100";
  if (score >= 80) return "80–89";
  if (score >= 70) return "70–79";
  return "Below 70";
}

/** Distance is filtered by range too — the bands a dispatcher actually asks in. */
export const DISTANCE_BANDS = ["Under 25 mi", "25–50 mi", "Over 50 mi"] as const;

export function distanceBand(mi: number): string {
  if (mi < 25) return "Under 25 mi";
  if (mi <= 50) return "25–50 mi";
  return "Over 50 mi";
}

/** Staff who own vendor relationships — used by the detail page's owner line. */
export const VENDOR_OWNERS = STAFF;

import type { ActivityEntry } from "./activity";

/**
 * Sales Console — Fuel Orders types.
 *
 * Structure and field names come from the FleetPanda Sales Console (the app
 * being recreated); every *visual* treatment comes from the DS.
 */
/**
 * THE ORDER'S STAGE (Pavan, 2026-10-07, taken from the Lovable Sales app):
 * Requested → Scheduled → Dispatched → Delivered, or Canceled. Replaces the
 * old Assigned / Unassigned, which only said whether a driver was picked.
 */
export type CoreFuelStage = "Requested" | "Scheduled" | "Dispatched" | "Delivered" | "Canceled";
/* A STAGE IS AN ID, NOT ONE OF FIVE WORDS (Pavan, 2026-10-07). Sales
   Settings can add stages between the five, so an order's stage is the core
   name or an added stage's `stage-…` id; `stageLabel` prints it. */
export type FuelOrderStatus = CoreFuelStage | (string & {});

/** Order type. The list column renders the code; the label is the tooltip. */
export type OrderTypeCode = "D" | "E";

export interface OrderType {
  code: OrderTypeCode;
  label: "Delivery" | "Extraction";
}

/**
 * When the delivery is planned. Rendered as two lines — date over time — and no
 * longer a from/to range.
 */
export interface PlannedAt {
  /** Formatted date, e.g. "Aug 24, 2026". */
  date: string;
  /** Formatted 12-hour time, e.g. "1:35 AM". */
  time: string;
}

/**
 * One product line on an order, with its own gallons. The row's Qty (Gal) is the
 * sum, and hovering it reveals this breakdown when there is more than one line.
 */
export interface ProductQty {
  name: string;
  gal: number;
}

/** Two-line cell: primary over a muted secondary. */
export interface TwoLine {
  title: string;
  description: string;
}

/** Person cell — initials avatar + name. `null` renders "— Unassigned". */
export interface Person {
  name: string;
  /** Avatar fallback initials, e.g. "ST". */
  initials: string;
}

export interface FuelOrder {
  id: string;
  /** col "Order #" — order number and the type badge share one cell */
  orderNo: string;
  type: OrderType;
  /** col "Customer" — customer name over ship-to */
  customer: TwoLine;
  /** col "Product" — product lines; the cell truncates past `PRODUCTS_SHOWN` */
  products: ProductQty[];
  /** col "Qty (Gal)" — the sum of `products`, derived when rows are built */
  qtyGal: number;
  /** col "Date of Delivery" — delivery date over its relative form */
  date: TwoLine;
  /** `YYYY-MM-DD` of the delivery date — what the toolbar date filter matches. */
  dateKey: string;
  /** col "Planned Date & Time" — date over time, or `null` for an em-dash */
  planned: PlannedAt | null;
  /** col "Tags" — free-form labels; the cell truncates past what fits */
  tags: string[];
  /** col "Status" */
  status: FuelOrderStatus;
  /** col "Driver" — `null` renders "— Unassigned" */
  driver: Person | null;
  /** The sheet's "Mark as Urgent" — kept on the order since 2026-10-07. */
  urgent: boolean;
  /** The change log — see `activity.tsx`. Written by the screen's setter. */
  audit?: ActivityEntry[];
  /* SALES SETTINGS' FIELDS (Pavan, 2026-10-07). What a field added on Form
     customization holds, by its key. */
  extra?: Record<string, string | boolean>;
  /** ISO — when the order entered its stage. The SLA clock. */
  stageSince?: string;
  /** The quote this order was made from, when it was. */
  fromQuote?: string;
  /** A move asked for and waiting on approval — the stage it would go to. */
  approvalFor?: string;
}

/**
 * The signed-in account. One shape for the top bar's avatar/menu and the
 * Profile page, so an edit on Profile is visible in the chrome immediately.
 * Structurally the DS's `TopBarUser`, restated here because the prototype owns
 * the state and the DS type is a prop contract, not a model.
 */
export interface AccountUser {
  name: string;
  email: string;
  /** Avatar fallback initials, e.g. "PS". */
  fallback: string;
  avatarSrc?: string;
}

import * as React from "react";
import { cn } from "@/lib/utils";

/*
  Single-select "Options" pills (Figma 27593:15012) — Low / Medium / High /
  Critical. The active pill fills; the rest are quiet surface chips.
*/
const OPTIONS = ["Low", "Medium", "High", "Critical"];

export function ChoicePills({ defaultValue = "Low" }: { defaultValue?: string }) {
  const [value, setValue] = React.useState(defaultValue);
  return (
    <div className="flex flex-wrap gap-2">
      {OPTIONS.map((opt) => {
        const active = value === opt;
        return (
          <button
            key={opt}
            type="button"
            onClick={() => setValue(opt)}
            aria-pressed={active}
            className={cn(
              "h-8 rounded-md px-3 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50",
              active
                ? "bg-foreground text-background"
                : "border border-border bg-fp-surface-1a text-foreground hover:border-fp-outline-2"
            )}
          >
            {opt}
          </button>
        );
      })}
    </div>
  );
}

import * as React from "react";
import { ChevronDown, Plus, Trash2, X, Check } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

/*
  Editable "Input / Dropdown Tables Layout" + "Add more and hover and delete"
  (Figma 27593:15012 / 27592:33634). Fully editable cells: dropdown cells (two
  lines, open a combobox list) and free-text cells, with required-column markers
  (*), a row-hover delete control, and a "+ Add more" row affordance.
*/

interface TableCellValue {
  title: string;
  description: string;
}

interface EditableRow {
  id: string;
  peripheral: TableCellValue;
  serial: string;
  condition: TableCellValue;
  ownership: TableCellValue;
}

const PERIPHERAL_OPTIONS = ["Scanner", "Printer", "Sensor", "Router"];
const CONDITION_OPTIONS = ["New", "Refurbished", "Used", "Damaged"];
const OWNERSHIP_OPTIONS = ["Owned", "Leased", "Rented", "Third-party"];

const emptyCell = (): TableCellValue => ({
  title: "Table Cell Text",
  description: "Description Text",
});

const makeRow = (id: string): EditableRow => ({
  id,
  peripheral: emptyCell(),
  serial: "",
  condition: emptyCell(),
  ownership: emptyCell(),
});

/** A two-line cell that opens a combobox list and writes the choice back. */
function CellSelect({
  value,
  options,
  onChange,
}: {
  value: TableCellValue;
  options: string[];
  onChange: (v: TableCellValue) => void;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          className={cn(
            // Fills the whole cell (no inset, no outline) — the hover/open
            // background covers the entire td, per the design. The cell sits on
            // Surface-1b, so the hover lift uses --accent to stay visible.
            "flex h-full w-full items-center justify-between gap-2 px-3 py-2.5 text-left outline-none transition-colors",
            "hover:bg-accent",
            "focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
            "data-[state=open]:bg-accent"
          )}
        >
          <span className="flex min-w-0 flex-col">
            <span className="truncate text-sm text-foreground">{value.title}</span>
            <span className="truncate text-xs text-muted-foreground">
              {value.description}
            </span>
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-44">
        {options.map((opt) => (
          <DropdownMenuItem
            key={opt}
            onSelect={() => onChange({ title: opt, description: value.description })}
          >
            {opt}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * A free-text cell that fills the whole td (no inner input box). Mirrors
 * CellSelect: borderless, full-cell hover lift, and inset focus ring while
 * typing. Carries the full set of input states:
 *  - default / filled → text-foreground (placeholder muted when empty)
 *  - hover            → bg-accent (same lift as the dropdown cells)
 *  - typing / focus   → inset ring + Surface-1a wash
 *  - disabled         → muted + not-allowed cursor
 */
function CellInput({
  value,
  onChange,
  placeholder,
  disabled,
}: {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  disabled?: boolean;
}) {
  return (
    // Absolutely fills the cell (the parent td is `relative`). A table cell
    // gives no definite height for `h-full` to resolve against, so `inset-0`
    // is what makes the hover/focus surface span the entire td.
    <label
      className={cn(
        "absolute inset-0 flex cursor-text items-stretch transition-colors",
        "hover:bg-accent",
        "focus-within:bg-fp-surface-1a focus-within:ring-2 focus-within:ring-inset focus-within:ring-ring/50",
        disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
      )}
    >
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        className={cn(
          "h-full w-full min-w-0 bg-transparent px-3 text-sm text-foreground outline-none",
          "placeholder:text-muted-foreground disabled:cursor-not-allowed"
        )}
      />
    </label>
  );
}

function RequiredLabel({ children, required }: { children: React.ReactNode; required?: boolean }) {
  return (
    <span className="text-sm font-medium text-foreground">
      {children}
      {required && <span className="text-destructive"> *</span>}
    </span>
  );
}

export function EditableTable() {
  const idRef = React.useRef(2);
  const [rows, setRows] = React.useState<EditableRow[]>([
    makeRow("er-1"),
    makeRow("er-2"),
  ]);
  // Row id whose delete is awaiting inline confirmation (✕ / red ✓).
  const [confirmId, setConfirmId] = React.useState<string | null>(null);
  // Add chip: icon-only until hovered/focused, then the label slides out.
  const [addExpanded, setAddExpanded] = React.useState(false);

  const update = (id: string, patch: Partial<EditableRow>) =>
    setRows((prev) => prev.map((r) => (r.id === id ? { ...r, ...patch } : r)));

  const addRow = () =>
    setRows((prev) => [...prev, makeRow(`er-${++idRef.current}`)]);

  const removeRow = (id: string) =>
    setRows((prev) => prev.filter((r) => r.id !== id));

  return (
    <div>
      {/* Bottom-left corner squared so the Add chip connects as an extension.
          T2 — the component IS the unit, ruled correct 2026-09-22 (7-variants
          §3); the attribute is how the boxed-tables check remembers that. */}
      <div
        data-table-variant="T2"
        className="overflow-hidden rounded-md rounded-bl-none border border-border"
      >
        <table className="w-full table-fixed border-collapse">
          {/* Last column is pinned to exactly 52px (the delete/confirm control).
              The four data columns keep their 26/22/26/26 proportions; in a
              fixed layout the browser reserves the 52px and scales the
              percentages to the remaining width. */}
          <colgroup>
            <col className="w-[26%]" />
            <col className="w-[22%]" />
            <col className="w-[26%]" />
            <col className="w-[26%]" />
            <col className="w-[52px]" />
          </colgroup>
          <thead>
            <tr className="border-b border-border bg-fp-table-header">
              <th className="px-3 py-2.5 text-left">
                <RequiredLabel required>Peripheral</RequiredLabel>
              </th>
              <th className="px-3 py-2.5 text-left">
                <RequiredLabel>Input/Text</RequiredLabel>
              </th>
              <th className="px-3 py-2.5 text-left">
                <RequiredLabel>Condition</RequiredLabel>
              </th>
              <th className="px-3 py-2.5 text-left">
                <RequiredLabel required>Ownership Status</RequiredLabel>
              </th>
              <th aria-hidden />
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr
                key={row.id}
                className="group/row border-b border-border last:border-b-0"
              >
                <td className="p-0 align-middle">
                  <CellSelect
                    value={row.peripheral}
                    options={PERIPHERAL_OPTIONS}
                    onChange={(v) => update(row.id, { peripheral: v })}
                  />
                </td>
                <td className="relative p-0 align-middle">
                  <CellInput
                    value={row.serial}
                    onChange={(v) => update(row.id, { serial: v })}
                    placeholder="Enter Serial No."
                  />
                </td>
                <td className="p-0 align-middle">
                  <CellSelect
                    value={row.condition}
                    options={CONDITION_OPTIONS}
                    onChange={(v) => update(row.id, { condition: v })}
                  />
                </td>
                <td className="p-0 align-middle">
                  <CellSelect
                    value={row.ownership}
                    options={OWNERSHIP_OPTIONS}
                    onChange={(v) => update(row.id, { ownership: v })}
                  />
                </td>
                {/* Last column — delete with inline confirm (Figma 28133:1526):
                    default → hover reveals trash → click swaps the same cell
                    space for a 52×52 vertical split: ✕ cancel (top, dark) over
                    ✓ confirm (bottom, red). */}
                <td className="p-0 align-middle">
                  {confirmId === row.id ? (
                    <div className="flex size-[52px] flex-col overflow-hidden rounded-md">
                      <button
                        type="button"
                        onClick={() => setConfirmId(null)}
                        aria-label="Cancel delete"
                        className="flex flex-1 items-center justify-center bg-fp-card-1 text-foreground outline-none transition-colors hover:bg-accent focus-visible:relative focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50"
                      >
                        <X className="size-4" />
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          removeRow(row.id);
                          setConfirmId(null);
                        }}
                        aria-label="Confirm delete"
                        className="flex flex-1 items-center justify-center bg-destructive text-white outline-none transition-colors hover:bg-destructive/90 focus-visible:relative focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50"
                      >
                        <Check className="size-4" />
                      </button>
                    </div>
                  ) : (
                    <button
                      type="button"
                      onClick={() => setConfirmId(row.id)}
                      aria-label="Delete row"
                      className="mx-auto flex size-7 items-center justify-center rounded-sm text-muted-foreground opacity-0 outline-none transition-[color,opacity,background-color] group-hover/row:opacity-100 hover:bg-destructive/15 hover:text-destructive focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
                    >
                      <Trash2 className="size-4" />
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Add a full row — a Surface-Base chip that connects to the table's
          bottom-left as an extension (squared top corners), sitting 1px below
          the table stroke. Icon-only until hover/focus, then "Add row" slides
          out. Hover is JS-driven so it's reliable inside the flex button. */}
      <Button
        variant="ghost"
        size="sm"
        onClick={addRow}
        onMouseEnter={() => setAddExpanded(true)}
        onMouseLeave={() => setAddExpanded(false)}
        onFocus={() => setAddExpanded(true)}
        onBlur={() => setAddExpanded(false)}
        className="mt-px h-7 gap-0 rounded-t-none rounded-b-md bg-background px-2 text-foreground hover:bg-background/80"
      >
        <Plus className="size-4 shrink-0" />
        <span
          className={cn(
            "overflow-hidden whitespace-nowrap transition-[max-width,opacity,padding] duration-200",
            addExpanded ? "max-w-[90px] pl-1.5 opacity-100" : "max-w-0 opacity-0"
          )}
        >
          Add row
        </span>
      </Button>
    </div>
  );
}

import * as React from "react";
import { FileText, Trash2, UploadCloud } from "lucide-react";
import { cn } from "@/lib/utils";

/*
  "Upload documents" (Figma 27593:15012). Three states from the design: an empty
  dropzone, an in-progress upload (circular progress + "Uploading N of M"), and
  uploaded file chips (type icon + name + size + preview/delete). Seeded to match
  the frame; the dropzone accepts new files and removal is live.
*/

export interface UploadedFile {
  id: string;
  name: string;
  size: string;
  kind: "PDF" | "DOC" | "PNG";
}

/* File-kind chips are categorical, not semantic — the hues come from the DS
   status/verified tokens so both themes track the token layer (never Tailwind's
   stock palette, whose -400 steps are tuned for dark grounds only). */
const KIND_STYLE: Record<UploadedFile["kind"], string> = {
  PDF: "bg-status-failed/15 text-status-failed",
  DOC: "bg-verified/15 text-verified",
  PNG: "bg-status-processing/15 text-status-processing",
};

const INITIAL_FILES: UploadedFile[] = [
  { id: "f1", name: "Signature format.pdf", size: "2.4mb", kind: "PDF" },
  { id: "f2", name: "Fees.doc", size: "2.4mb", kind: "DOC" },
  { id: "f3", name: "Conditions.png", size: "2.4mb", kind: "PNG" },
];

const NOTE =
  "Note: Upload files in .JPG, .PNG, .PDF, or .DOC format. Files must be under 5 MB in total.";

/** Determinate circular progress ring. */
function CircularProgress({ value }: { value: number }) {
  const r = 18;
  const c = 2 * Math.PI * r;
  return (
    <span className="relative inline-flex size-11 items-center justify-center">
      <svg className="size-11 -rotate-90" viewBox="0 0 44 44">
        <circle
          cx="22"
          cy="22"
          r={r}
          fill="none"
          strokeWidth="3"
          className="stroke-muted"
        />
        <circle
          cx="22"
          cy="22"
          r={r}
          fill="none"
          strokeWidth="3"
          strokeLinecap="round"
          className="stroke-primary"
          strokeDasharray={c}
          strokeDashoffset={c * (1 - value / 100)}
        />
      </svg>
      <span className="absolute text-[11px] font-medium tabular-nums">
        {value}%
      </span>
    </span>
  );
}

export interface FileUploadProps {
  /**
   * `showcase` renders all three states at once — empty dropzone, an
   * in-progress example, and seeded chips — which is what the gallery needs and
   * what every existing caller gets by default.
   *
   * `field` renders the control a real form needs: dropzone, note, and only the
   * files actually added. No seeded files, no fake progress.
   */
  variant?: "showcase" | "field";
  /** Dropzone label. */
  label?: string;
  /** The format/size note under the dropzone. */
  note?: string;
  /** The files picked so far, whenever the list changes — for a caller that
   *  has to act on them (attach, send). Optional; the control works alone. */
  onFilesChange?: (files: UploadedFile[]) => void;
  /** Passed to the file input — e.g. `"image/*"`. */
  accept?: string;
}

export function FileUpload({
  variant = "showcase",
  label = "Upload Documents",
  note = NOTE,
  onFilesChange,
  accept,
}: FileUploadProps = {}) {
  const showcase = variant === "showcase";
  const [files, setFiles] = React.useState<UploadedFile[]>(
    showcase ? INITIAL_FILES : [],
  );
  const idRef = React.useRef(INITIAL_FILES.length);
  const reported = React.useRef(onFilesChange);
  React.useEffect(() => {
    reported.current = onFilesChange;
  });
  React.useEffect(() => {
    if (!showcase) reported.current?.(files);
  }, [files, showcase]);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const [dragOver, setDragOver] = React.useState(false);

  const inferKind = (name: string): UploadedFile["kind"] => {
    const ext = name.split(".").pop()?.toLowerCase();
    if (ext === "doc" || ext === "docx") return "DOC";
    if (ext === "png" || ext === "jpg" || ext === "jpeg") return "PNG";
    return "PDF";
  };

  const addFiles = (list: FileList | null) => {
    if (!list) return;
    const next = Array.from(list).map((f) => ({
      id: `f${++idRef.current}`,
      name: f.name,
      size: `${(f.size / 1_000_000).toFixed(1)}mb`,
      kind: inferKind(f.name),
    }));
    setFiles((prev) => [...prev, ...next]);
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Dropzone + its note are ONE unit, 4px apart — the note describes the
          control above it, not the list below. */}
      <div className="flex flex-col gap-1">
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          onDragOver={(e) => {
            e.preventDefault();
            setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onDrop={(e) => {
            e.preventDefault();
            setDragOver(false);
            addFiles(e.dataTransfer.files);
          }}
          className={cn(
            /* TRANSPARENT AT REST — an empty dropzone is a 96px hole in the
               form, and a filled one made it the largest painted shape on the
               page for the field least often used. The dashed rim is the whole
               affordance; the fill was only saying "something goes here" a
               second time, louder. Transparent also means the zone inherits
               whatever it is dropped into — the white content layer, a card, a
               tinted panel — instead of pinning one surface value that is
               right in exactly one of those places.

               A FILL ON DRAG, though: while a file is over it the zone has to
               say it will catch it, and that is the one moment the extra
               weight is information rather than decoration. */
            "flex h-24 w-full items-center justify-center gap-2 rounded-md border bg-transparent text-sm outline-none transition-colors",
            dragOver
              ? "border-ring bg-accent"
              : "border-border hover:border-fp-outline-2",
            "focus-visible:ring-2 focus-visible:ring-ring/50",
          )}
        >
          <UploadCloud className="size-5 text-muted-foreground" />
          <span className="font-medium">{label}</span>
          <input
            ref={inputRef}
            type="file"
            multiple
            accept={accept}
            className="hidden"
            onChange={(e) => addFiles(e.target.files)}
          />
        </button>
        <p className="text-xs text-muted-foreground">{note}</p>
      </div>

      {/* The in-progress state is a STATE, not a permanent block — it belongs in
          the showcase, never on a form where nothing is uploading. */}
      {showcase && (
        <div className="flex flex-col gap-1">
          <div className="flex h-24 w-full items-center justify-center gap-3 rounded-md border border-border bg-fp-surface-1a">
            <CircularProgress value={75} />
            <span className="text-sm">Uploading 2 of 3</span>
          </div>
          <p className="text-xs text-muted-foreground">{note}</p>
        </div>
      )}

      {/* Uploaded chips. A CHIP IS SIZED BY ITS CONTENT, not by the container:
          a filename and a file size need about 240px, and a three-column grid
          across a wide sheet stretched each one to twice that for no reader's
          benefit. They wrap, so more files fill the row rather than the row
          growing to fit. */}
      <div className="flex flex-wrap gap-3">
        {files.map((file) => (
          <div
            key={file.id}
            className="flex w-60 items-center gap-3 rounded-md border border-border bg-fp-surface-1a px-3 py-2.5"
          >
            <span
              className={cn(
                "flex size-9 shrink-0 items-center justify-center rounded-md text-[10px] font-semibold",
                KIND_STYLE[file.kind],
              )}
            >
              <FileText className="size-4" />
            </span>
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="truncate text-sm font-medium">{file.name}</span>
              <span className="text-xs text-muted-foreground">{file.size}</span>
            </span>
            <button
              type="button"
              aria-label={`Delete ${file.name}`}
              onClick={() =>
                setFiles((prev) => prev.filter((f) => f.id !== file.id))
              }
              className="flex size-7 items-center justify-center rounded-sm text-muted-foreground outline-none transition-colors hover:bg-destructive/15 hover:text-destructive focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <Trash2 className="size-4" />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

import * as React from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Slider } from "@/components/ui/slider";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Field as UIField,
  FieldDescription,
  FieldError,
  FieldLabel,
  FieldLegend,
  FieldSet,
} from "@/components/ui/field";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { EditableTable } from "./EditableTable";
import { FileUpload } from "./FileUpload";
