/** Compact numeric pager (Figma wide variant shows just page numbers). */
function MiniPagination({
  page,
  total,
  onChange,
}: {
  page: number;
  total: number;
  onChange: (p: number) => void;
}) {
  return (
    <div className="flex items-center justify-end gap-1 p-3">
