import * as React from "react";
import { useMemo } from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";

/**
 * Field family — Figma "Field" (18684:15220) + siblings. The systematic form-
 * composition layer: every control gets a consistent, accessible scaffold
 * (label / description / error / grouping / legend / separator). Pure layout +
 * semantics, no new dependency — composes Label + Separator.
 *
 * Figma → code map:
 *   Field set            → Field + FieldLabel + FieldDescription + FieldError + FieldContent
 *   Field / Legend       → FieldSet + FieldLegend (variant: legend | label)
 *   Field Group (H/V)    → FieldGroup
 *   Field / Separator    → FieldSeparator
 * Variants: Orientation (vertical | responsive | horizontal), Data Invalid
 * (`data-invalid`), Description Placement (DOM order of FieldDescription).
 */
function FieldSet({ className, ...props }: React.ComponentProps<"fieldset">) {
  return (
    <fieldset
      data-slot="field-set"
      className={cn(
        "flex flex-col gap-6",
        "has-[>[data-slot=checkbox-group]]:gap-3 has-[>[data-slot=radio-group]]:gap-3",
        className
      )}
      {...props}
    />
  );
}

function FieldLegend({
  className,
  variant = "legend",
  ...props
}: React.ComponentProps<"legend"> & { variant?: "legend" | "label" }) {
  return (
    <legend
      data-slot="field-legend"
      data-variant={variant}
      className={cn(
        "mb-3 font-medium",
        "data-[variant=legend]:text-base",
        "data-[variant=label]:text-sm",
        className
      )}
      {...props}
    />
  );
}

function FieldGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-group"
      className={cn(
        "group/field-group @container/field-group flex w-full flex-col gap-7 data-[slot=checkbox-group]:gap-3 [&>[data-slot=field-group]]:gap-4",
        className
      )}
      {...props}
    />
  );
}

const fieldVariants = cva(
  "group/field flex w-full gap-3 data-[invalid=true]:text-destructive",
  {
    variants: {
      orientation: {
        vertical: ["flex-col [&>*]:w-full [&>.sr-only]:w-auto"],
        horizontal: [
          "flex-row items-center",
          "[&>[data-slot=field-label]]:flex-auto",
          "has-[>[data-slot=field-content]]:items-start has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
        ],
        responsive: [
          "flex-col @md/field-group:flex-row @md/field-group:items-center [&>*]:w-full @md/field-group:[&>*]:w-auto [&>.sr-only]:w-auto",
          "@md/field-group:[&>[data-slot=field-label]]:flex-auto",
          "@md/field-group:has-[>[data-slot=field-content]]:items-start @md/field-group:has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
        ],
      },
    },
    defaultVariants: {
      orientation: "vertical",
    },
  }
);

function Field({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof fieldVariants>) {
  return (
    <div
      role="group"
      data-slot="field"
      data-orientation={orientation}
      className={cn(fieldVariants({ orientation }), className)}
      {...props}
    />
  );
}

function FieldContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-content"
      className={cn(
        "group/field-content flex flex-1 flex-col gap-1.5 leading-snug",
        className
      )}
      {...props}
    />
  );
}

function FieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      data-slot="field-label"
      className={cn(
        "group/field-label peer/field-label flex w-fit gap-2 leading-snug group-data-[disabled=true]/field:opacity-50",
        "has-[>[data-slot=field]]:w-full has-[>[data-slot=field]]:flex-col has-[>[data-slot=field]]:rounded-md has-[>[data-slot=field]]:border [&>*]:data-[slot=field]:p-4",
        "has-data-[state=checked]:border-primary has-data-[state=checked]:bg-primary/5 dark:has-data-[state=checked]:bg-primary/10",
        className
      )}
      {...props}
    />
  );
}

function FieldTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-label"
      className={cn(
        "flex w-fit items-center gap-2 text-sm leading-snug font-medium group-data-[disabled=true]/field:opacity-50",
        className
      )}
      {...props}
    />
  );
}

function FieldDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="field-description"
      className={cn(
        "text-sm leading-normal font-normal text-muted-foreground group-has-[[data-orientation=horizontal]]/field:text-balance",
        "last:mt-0 nth-last-2:-mt-1 [[data-variant=legend]+&]:-mt-1.5",
        "[&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary",
        className
      )}
      {...props}
    />
  );
}

function FieldSeparator({
  children,
  className,
  ...props
}: React.ComponentProps<"div"> & {
  children?: React.ReactNode;
}) {
  return (
    <div
      data-slot="field-separator"
      data-content={!!children}
      className={cn(
        "relative -my-2 h-5 text-sm group-data-[variant=outline]/field-group:-mb-2",
        className
      )}
      {...props}
    >
      <Separator className="absolute inset-0 top-1/2" />
      {children && (
        <span
          className="relative mx-auto block w-fit bg-background px-2 text-muted-foreground"
          data-slot="field-separator-content"
        >
          {children}
        </span>
      )}
    </div>
  );
}

function FieldError({
  className,
  children,
  errors,
  ...props
}: React.ComponentProps<"div"> & {
  errors?: Array<{ message?: string } | undefined>;
}) {
  const content = useMemo(() => {
    if (children) {
      return children;
    }

    if (!errors?.length) {
      return null;
    }

    const uniqueErrors = [
      ...new Map(errors.map((error) => [error?.message, error])).values(),
    ];

    if (uniqueErrors?.length == 1) {
      return uniqueErrors[0]?.message;
    }

    return (
      <ul className="ml-4 flex list-disc flex-col gap-1">
        {uniqueErrors.map(
          (error, index) =>
            error?.message && <li key={index}>{error.message}</li>
        )}
      </ul>
    );
  }, [children, errors]);

  if (!content) {
    return null;
  }

  return (
    <div
      role="alert"
      data-slot="field-error"
      className={cn("text-sm font-normal text-destructive", className)}
      {...props}
    >
      {content}
    </div>
  );
}

export {
  Field,
  FieldLabel,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLegend,
  FieldSeparator,
  FieldSet,
  FieldContent,
  FieldTitle,
};

import { cn } from "@/lib/utils";

/*
  FILE TYPE ICON (Pavan, 2026-10-14) — a document outline with its format on
  a tag, beside every uploaded file's name: PDF, PNG, SVG, JPG, DOC, XLS, CSV…
  After his reference (a file with a "PDF" tag on its left edge).

  THE TAG'S COLOUR SAYS THE FAMILY, so a list can be scanned by kind: PDF red
  · images violet · documents blue · spreadsheets green · archives orange ·
  anything else ink. The text on the tag carries the format, so colour is
  never the only cue. Lane tokens — the same in both themes.
*/

const FAMILY: Record<string, string> = {
  pdf: "bg-fp-lane-red",
  png: "bg-fp-lane-violet",
  jpg: "bg-fp-lane-violet",
  jpeg: "bg-fp-lane-violet",
  gif: "bg-fp-lane-violet",
  svg: "bg-fp-lane-violet",
  webp: "bg-fp-lane-violet",
  heic: "bg-fp-lane-violet",
  doc: "bg-fp-lane-blue",
  docx: "bg-fp-lane-blue",
  txt: "bg-fp-lane-blue",
  rtf: "bg-fp-lane-blue",
  xls: "bg-fp-lane-green",
  xlsx: "bg-fp-lane-green",
  csv: "bg-fp-lane-green",
  zip: "bg-fp-lane-orange",
};

/** The file's extension, from its name — "" when it has none. */
export const extensionOf = (name: string) => {
  const m = /\.([a-z0-9]{1,5})$/i.exec(name.trim());
  return m ? m[1].toLowerCase() : "";
};

export function FileTypeIcon({ name, className }: { name: string; className?: string }) {
  const ext = extensionOf(name);
  const label = (ext === "jpeg" ? "jpg" : ext || "file").slice(0, 4).toUpperCase();
  return (
    <span aria-hidden data-slot="file-type-icon" className={cn("relative inline-flex h-7 w-6 shrink-0", className)}>
      {/* THE SHEET — an outline with a folded corner. */}
      <svg viewBox="0 0 24 28" className="size-full text-foreground/70" fill="none">
        <path
          d="M5 1.5h9.5L21.5 8.5V24.5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-21a2 2 0 0 1 2-2Z"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinejoin="round"
        />
        <path d="M14.5 1.5v5a2 2 0 0 0 2 2h5" stroke="currentColor" strokeWidth="1.5" strokeLinejoin="round" />
        <path d="M8 19.5h9M8 22.5h6" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
      </svg>
      {/* THE FORMAT — on a tag over the sheet's left edge. */}
      <span
        className={cn(
          "absolute top-[9px] -left-1 rounded-[3px] px-[3px] py-px text-[7px] leading-none font-bold tracking-wide",
          FAMILY[ext] ? `${FAMILY[ext]} text-white` : "bg-foreground text-background"
        )}
      >
        {label}
      </span>
    </span>
  );
}

import * as React from "react";
import { HoverCard as HoverCardPrimitive } from "radix-ui";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

function HoverCard({
  ...props
}: React.ComponentProps<typeof HoverCardPrimitive.Root>) {
  return <HoverCardPrimitive.Root data-slot="hover-card" {...props} />;
}

/**
 * Trigger States — Figma "Hover Card / Trigger" (216:3085). The `link` variant
 * bakes the documented states so call sites don't hand-roll them:
 *   Default → plain · Hover → underline · Focus → ring · Disabled → dimmed.
 * Omit `variant` (or pass `asChild`) for the bare pass-through used when the
 * trigger is a custom element.
 */
const hoverCardTriggerVariants = cva(
  "inline-flex w-fit cursor-pointer items-center rounded-sm font-medium text-foreground underline-offset-4 outline-none transition-colors hover:underline focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: { variant: { link: "" } },
  }
);

function HoverCardTrigger({
  className,
  variant,
  children,
  asChild,
  ...props
}: React.ComponentProps<typeof HoverCardPrimitive.Trigger> &
  VariantProps<typeof hoverCardTriggerVariants>) {
  // A variant renders its own focusable <button>; without one, pass through
  // (preserving the existing `asChild` API for custom trigger elements).
  if (variant) {
    return (
      <HoverCardPrimitive.Trigger data-slot="hover-card-trigger" asChild>
        <button
          className={cn(hoverCardTriggerVariants({ variant }), className)}
          {...(props as React.ComponentProps<"button">)}
          type="button"
        >
          {children}
        </button>
      </HoverCardPrimitive.Trigger>
    );
  }
  return (
